(window.__BOOKS=window.__BOOKS||{})["e_electra"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">в порядке их появления на сцену</span>"],["person","<span class=\"pn\">Микенский пахарь</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Электра, его названая жена</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"orest\">Орест</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Пилад (без речей)</span>"],["person","<span class=\"pn\">Хор из местных девушек</span>"],["person","<span class=\"pn\">Корифей — старшая девушка</span>"],["person","<span class=\"pn\">Старый дядька Агамемнона</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Клитемнестра, при ней свита из фригийских пленниц</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Диоскуры (говорит Кастор)</span>"],["place","Действие происходит в Аргосе, недалеко от границы, перед бедной деревенской хижиной."],["act","Пролог","a1",""],["sd","Лунная ночь на исходе. Бедная лачуга. Вдали спуск к реке, в волнах которой, колеблясь, отражается луна. Перед домом бедный алтарь Аполлона."],["scene","Явление первое","s1",1,1],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["dir","выходит из лачуги, неся в руках упряжь"],["v","О древний край аргосский, о Инах!<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,1,1,0],["v","Из ваших вод когда-то Агамемнон",0,2,0,0],["v","Свой гордый флот под Трою уводил,",0,3,0,0],["v","Чтоб там, убив державного Приама,",0,4,0,0],["v","Дарданские твердыни сокрушить",0,5,0,0],["v","И варварской бессчетною добычей",0,6,0,0],["v","Измерить высь аргосских храмов… Да…",0,7,0,0],["sd","Пауза."],["v","Он за морем был счастлив, а в Микены",0,8,1,0],["v","Вернулся, чтоб погибнуть от сетей",0,9,1,0],["v","Своей жены, под дланию Эгисфа.",0,10,1,1],["sd","(Приостанавливается, потом тише и изменившимся голосом.)"],["v","Когда, свой древний скипетр уронив,",0,10,1,0],["v","Сраженный царь упал, Фиеста чадо",0,11,1,0],["v","Прияло трон Атридов и его",0,12,1,0],["v","Жену, Тиндара дочь. Атридом дети",0,13,1,0],["v","Оставлены здесь были — до войны:",0,14,1,0],["v","Дитя <span class=\"ch\" data-ch=\"orest\">Орест</span> и нежный цвет <span class=\"ch\" data-ch=\"elektra\">Электра</span>, —",0,15,1,0],["v","Так мальчика Фиестов сын убить",0,15,1,0],["v","Готовился, да спас его кормилец",0,16,1,0],["v","И к Строфию, фокидскому царю,",0,17,1,0],["v","Украдкою дитя унес, а в отчем",0,18,1,0],["v","Чертоге дочь осталась. И ее,",0,19,1,0],["v","Чуть расцвела, со всей Эллады сватать",0,20,1,1],["v","Съезжалась знать.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,20,1,0],["v","Трепещущий Эгисф,",1,20,0,0],["v","Да не родит царевна от вельможи",0,21,1,0],["v","Атриду внука-мстителя, ее",0,22,1,0],["v","От женихов запрятал дальше в терем,",0,23,1,0],["v","Но не обрел покоя: будто сына",0,24,1,0],["v","Вельможе дать нельзя и под замком.",0,25,1,0],["sd","(Помолчав.)"],["v","К детенышу и у волчихи в сердце",0,25,1,0],["v","Любовь живет, и <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> — мать —",0,26,1,0],["v","<span class=\"ch\" data-ch=\"elektra\">Электру</span> от ножа его спасает…<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,27,1,0],["v","Ведь, чтоб зарезать мужа, хоть предлог",0,28,1,0],["v","Она имела, а за кровь детей",0,29,1,0],["v","Ей ненависть грозила без пощады.",0,30,1,1],["v","Фиестов сын придумал наконец:",0,30,1,0],["v","За голову бежавшего <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,31,1,0],["v","Он золота убийцам посулил,",0,32,1,0],["v","А дочь царя мне в жены он вручает.",0,33,1,0],["v","Микенец я исконный: древний род",0,33,2,0],["v","Порочить свой, конечно, я не буду.",0,34,1,0],["v","Но что она, благая кровь, коль ей",0,35,1,0],["v","Богатством не венчаться? Злая бедность",0,36,1,0],["v","Задушит славу имени. Эгисф",0,36,1,0],["v","Рассчитывал, что, обручив царевну",0,37,1,0],["v","Ничтожному, он на ничто сведет",0,38,1,0],["v","И самую опасность. Ведь, пожалуй,",0,39,1,0],["v","Вельможный зять молву бы окрылил,",0,40,1,1],["v","Он карой бы грозил убийце тестя…",0,40,1,0],["sd","(Помолчав.)"],["v","О, избранный Эгисфом бедный муж",0,41,1,0],["v","Царевнина не опорочил ложа:",0,42,1,0],["v","Она чиста — Кипридою клянусь.",0,43,1,0],["v","Да, я бы счел позором над девицей,",0,44,1,0],["v","Рожденною в чертоге, коль ее",0,45,1,0],["v","Мне случай в жены отдал, издеваться…",0,45,1,0],["v","И стоны грудь вздымают мне, когда",0,46,1,0],["v","Подумаю, что если нареченный",0,47,1,0],["v","Наш зять <span class=\"ch\" data-ch=\"orest\">Орест</span> вернется в Аргос и",0,48,1,0],["v","Несчастный брак сестры своей увидит…",0,49,1,0],["v","И если кто безумцем назовет",0,50,1,1],["v","Меня за то, что ложа девы юной",0,50,1,0],["v","Я, муж ее, коснуться не дерзну,",0,51,1,0],["v","Пускай своей других не мерит мерой",0,52,1,0],["v","И скромного хоть вчуже, да почтит…",0,53,1,0],["sd","(Отходит в сторону и перебирает упряжь.)"],["scene","Явление второе","s2",1,2],["sd","Из дома выходит <span class=\"ch\" data-ch=\"elektra\">Электра</span>, худая, бледная, с воспаленными горящими глазами; черные остриженные волосы, темный и грубый пеплос; ставит на голову кувшин, готовясь идти к реке за водою."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О ночь, о мать, светила золотые",0,53,0,0],["v","Вскормившая… Царевну и кувшин",0,54,0,0],["v","На голове у ней и спуск ты видишь",0,55,0,0],["v","К реке… О, знай, что это не нужда",0,56,0,0],["v","Меня подъемлет с ложа, — злая дерзость",0,56,0,0],["v","Эгисфова шлет стоны из моей",0,57,0,0],["v","Груди в простор небес к отцовской тени…",0,58,0,0],["v","Злодейка-мать в угоду своему",0,59,0,0],["v","Любовнику, <span class=\"ch\" data-ch=\"elektra\">Электре</span> Тиндарида",0,60,0,1],["v","Закрыла дверь чертога и, прижив",0,61,0,0],["v","Других детей с Эгисфом, мне и брату",0,62,0,0],["v","У очага приюта не дает.",0,63,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["dir","видя ее, подходит, и ласково"],["v","Что мучишься, несчастная? Тебе ли",0,64,0,0],["v","Наш грубый труд? Ты в неге рождена…",0,65,0,0],["v","Не я ль просил: «Электра, брось работать»?",0,66,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ты зол моих позором не венчал:",0,67,0,0],["v","Как бога, чту тебя я. О, для смертных",0,68,0,0],["v","В несчастии найти врача такого,",0,70,0,1],["v","Каким ты мне явился, — это клад…",0,70,0,0],["v","И буду ль ждать приказа я, чтоб бремя",0,71,0,0],["v","Твоих трудов делить с тобою, милый?",0,72,0,0],["v","Иль мало в поле дела у тебя…",0,73,0,0],["v","Оставь мне дом! Приехав с нивы, пахарь",0,74,0,0],["v","Пойдет ли сам к обеду за водой?..",0,75,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["dir","улыбаясь"],["v","Ну, потрудись, коли своя охота,",0,76,0,0],["v","Да благо ж и вода недалеко…",0,77,0,0],["v","А мне сбираться, видно… чуть забрезжит,",0,78,0,0],["v","Быков веду на ниву — нынче сев.",0,79,0,0],["v","Да, кто ленив, пусть с уст его не сходят",0,80,0,1],["v","Слова молитв, а хлеба не сберег.",0,80,0,0],["sd","Уходят оба. <span class=\"ch\" data-ch=\"elektra\">Электра</span> спускается на реку и долго видна, пахарь в поле налево."],["scene","Явление третье","s3",1,3],["sd","Справа входят <span class=\"ch\" data-ch=\"orest\">Орест</span> и Пилад с небольшой свитой; они в коротких и темных перекидках, вместо шлемов у них войлочные шляпы, вроде той, в которой изображают Гермеса, и короткие мечи."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О мой Пилад, для бедного <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,81,0,0],["v","Ты — первый и последний друг: когда",0,82,0,0],["v","Эгисф и мать проклятая моя",0,83,0,0],["v","Вдвоем отца убили и пришлось мне",0,84,0,0],["v","Весь этот ужас пережить, один",0,85,0,0],["v","Ты от меня, Пилад, не отвернулся.",0,85,0,0],["v","Сюда, в Аргосский край, меня ведет",0,86,0,0],["v","Вещание оракула — об этом",0,87,0,0],["v","Я никому не говорил, но кровь",0,88,0,0],["v","Отцовская здесь отольется кровью",0,89,0,0],["v","Его убийц. Сегодня ночью там,",0,90,0,1],["v","У гроба, я и плакал, и волос",0,91,0,0],["v","Оставил первый локон, кровь овечью",0,92,0,0],["v","Тайком от нового владыки пролил.",0,93,0,0],["v","Но в город не войду я; две причины",0,94,0,0],["v","На это есть: во-первых, если нас",0,95,0,0],["v","Шпион какой узнает, можно скрыться",0,96,0,0],["v","В соседний край; да и желал бы я",0,97,0,0],["v","Сестру найти — по слухам, замуж вышла",0,98,0,0],["v","Она, и терем девичий забыт.",0,99,0,0],["v","А в мести мне сестра поможет, верно…",0,100,0,1],["v","Через нее узнаю, что у нас",0,100,0,0],["v","Творится в доме отчем…",0,101,0,0],["sd","(Встает.)"],["v","Но на небе",0,102,4,0],["v","Свой белый лик заря уж кажет: да,",0,103,0,0],["v","Приходится с пути свернуть, — быть может,",0,104,0,0],["v","Иль пахаря мы встретим, иль рабу",0,105,0,0],["v","И нам они откроют, где жилище",0,105,0,0],["v","Электрино…",0,106,0,0],["sd","(Оглядывается и видит приближающуюся <span class=\"ch\" data-ch=\"elektra\">Электру</span>, которая идет, еле передвигая ноги, поднимаясь в гору, с тяжелым кувшином на голове.)"],["v","Смотри, Пилад, как раз",0,107,4,0],["v","Служанка по воду к реке спускалась, видно,",0,108,0,0],["v","Кувшин несет; послушаем, из уст",0,109,0,0],["v","Не вырвется ль у ней, на наше счастье,",0,110,0,1],["v","Намек какой… довольно слова… тс-с…",0,111,0,0],["sd","Прячется, и свита, по знаку <span class=\"ch\" data-ch=\"orest\">Ореста</span>, тоже. Зрителям они видны, но не заметны ни <span class=\"ch\" data-ch=\"elektra\">Электре</span>, ни хору, который должен скоро войти на сцену. Во время двух следующих явлений — между ними мимическая сцена."],["scene","Явление четвертое","s4",1,4],["sd","Те же и <span class=\"ch\" data-ch=\"elektra\">Электра</span>."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["str","Строфа I"],["v","О, не медли, не медли, заря встает…",0,112,0,0],["v","И выше, выше, плача, вздымайся…",0,113,0,0],["v","О, тяжко!",1,113,0,0],["v","Я от корня Атридова,",0,114,1,0],["v","Тиндарида жестокая<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,115,1,0],["v","Нежный цвет принесла царю…",0,116,1,0],["v","Но в аргосских слыву устах",0,117,1,0],["v","Я бедной <span class=\"ch\" data-ch=\"elektra\">Электрой</span>.",0,118,1,0],["v","Злом и мукой повита я,",0,120,1,1],["v","Горем вспоена.",0,121,1,0],["v","Ты ж, отец, адской тьмой одет,",0,122,1,0],["v","Ложа брачной подругой убит, лежишь",0,123,1,0],["v","И Эгисфом с нею зарезан…",0,124,1,0],["sd","(Плачет.)"],["v","Улетайте, рыдая, стоны!",0,125,0,0],["v","Сердцу пить чашу слез так сладко…",0,126,0,0],["str","Антистрофа I"],["v","О, не медли, не медли, заря встает…",0,127,0,0],["v","И выше, выше, плача, вздымайся…",0,128,0,0],["v","О, тяжко!",1,128,0,0],["v","Где твой город, где дом, скажи,",0,130,0,1],["v","Бедный брат? С кем ты делишь хлеб?",0,130,0,0],["v","И зачем среди зла и слез",0,131,0,0],["v","В отчем тереме кинул ты",0,132,0,0],["v","Электру, Электру?",0,132,0,0],["v","Ты придешь ли к страдалице",0,133,0,0],["v","Цепь сорвать с нее?",0,134,0,0],["v","Боже вышний, за кровь отца",0,135,0,0],["v","Принести сюда алчущий мести меч",0,135,0,0],["v","Дай, о Зевс, скитальцу <span class=\"ch\" data-ch=\"orest\">Оресту</span>!",0,136,0,0],["v","Улетайте, рыдая, стоны!",0,137,0,0],["v","Сердцу пить чашу слез так сладко…",0,137,0,0],["sd","(Приходит к хижине и, сняв кувшин, ставит его на землю.)"],["str","Строфа II"],["v","Тяжкое бремя… Довольно…",0,138,0,0],["sd","(простирая руки к небу.)"],["v","А ты, что рыданьем",0,139,4,0],["v","Ночи оплакан… Заря занялась.",0,140,0,1],["v","Слышишь, родимый?",0,141,0,0],["v","О, внемли же песне надгробной!",0,142,1,0],["v","Плача, я из могилы зову тебя.",0,143,1,0],["v","День и ночь, день и ночь я",0,144,1,0],["v","Изнываю — ланиты в кровь",0,145,1,0],["v","Острым ногтем разорваны",0,146,1,0],["v","И избито чело мое",0,147,1,0],["v","В честь тебя, царь-отец мой…",0,148,1,0],["str","Месод"],["v","Не жалей, не жалей ланит.",0,150,0,1],["v","Слышишь: там",0,150,1,0],["v","У ручья и тоскует и мечется,",0,151,0,0],["v","Плача, лебедь-детеныш, отца зовет,",0,152,0,0],["v","Крепкой сетью покрытого,",0,152,0,0],["v","Так в слезах я зову тебя,",0,153,0,0],["v","Так, несчастный, тебе я молюсь, отец.",0,154,0,0],["str","Антистрофа II"],["v","Только что тело омыть ты склонился, родимый,",0,155,0,0],["v","Смерти объятья открылись тебе…",0,155,0,0],["v","О, что за мука!..",0,156,1,0],["v","О, секиры удар ужасный,",0,157,1,0],["v","И в чертогах, о, ужас свидания!..",0,157,1,0],["v","Не в цветах и не с лентами",0,158,1,0],["v","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> тебя ждала,",0,159,1,0],["v","А с секирой отточенной,",0,160,1,1],["v","Чтоб Эгисфу царя отдать,",0,161,1,0],["v","Ложа хитрому другу.",0,162,1,0],["scene","Явление пятое","s5",1,5],["sd","На сцену поднимаются девушки из окрестных местностей. Во время следующего парода они располагаются вокруг алтаря."],["v","Хор (первое полухорие)",0,163,0,0],["str","Строфа I"],["v","Здравствуй, дочь Агамемнона!",0,164,0,0],["v","Я, о царевна, и в этой глуши не забыла <span class=\"ch\" data-ch=\"elektra\">Электру</span>.",0,165,0,0],["sd","(Подходя к царевне.)"],["v","На молоке вспоен,",0,166,3,0],["v","Горный пастух вчера",0,167,3,0],["v","Весть из Микен принес:",0,170,3,1],["v","Завтра к владычице",0,171,3,0],["v","Гере в Аргосский храм",0,172,3,0],["v","Девы сбираются:<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,173,3,0],["v","Праздник, Электра, нам.",0,174,3,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["str","Строфа II"],["v","О, душа не рвется, девы,",0,175,0,0],["v","Из груди моей к веселью.",0,176,0,0],["v","Ожерелья золотого",0,177,0,0],["v","Не хочу я, и ногою",0,178,0,0],["v","Гибкой я меж дев аргосских",0,180,0,1],["v","В хороводе уж не буду",0,180,0,0],["v","Попирать родимой нивы.",0,181,0,0],["v","Пляску мне заменят слезы…",0,182,0,0],["v","Посмотри: где локон нежный?",0,183,0,0],["v","Видишь — пеплос весь в лохмотьях…",0,184,0,0],["v","Это ль доля дочки царской,",0,185,0,0],["v","Гордой дочери Атрида?",0,186,0,0],["v","И на то ли Агамемнон",0,187,0,0],["v","Трою царственную рушил?",0,188,0,0],["v","Хор (второе полухорие)",0,189,0,0],["sd","(подавая <span class=\"ch\" data-ch=\"elektra\">Электре</span> роскошно затканный пеплос и золотое ожерелье)"],["str","Антистрофа I"],["v","О, не спорь с великой Герой!",0,190,0,1],["v","Вот тебе платья расшитые, ты их наденешь, <span class=\"ch\" data-ch=\"elektra\">Электра</span>.",0,190,0,0],["v","А золотой убор,",0,191,0,0],["v","Как он пойдет к тебе!",0,192,0,0],["v","Или слезами ты,",0,193,0,0],["v","Если богов не чтишь,",0,194,0,0],["v","Станешь сильней врага…",0,195,0,0],["v","Лучше молись, дитя:",0,196,0,0],["v","Будешь блаженна ты…",0,197,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","обращаясь ко второму полухорию"],["str","Строфа II"],["v","О, давно, со дня убийства,",0,198,0,0],["v","Ни один из них, бессмертных,",0,199,0,0],["v","От <span class=\"ch\" data-ch=\"elektra\">Электры</span> горемычной",0,200,0,1],["v","Жертвы, дева, не приемлет.",0,201,0,0],["v","Горе вам, останкам отчим,",0,202,0,0],["v","Горе и скитальцу-брату,",0,203,0,0],["v","В той земле, куда прибрел он,",0,204,0,0],["v","Где, в толпе рабов затерян,",0,205,0,0],["v","К очагу он не подходит,",0,206,0,0],["v","Он, наследник славы отчей.",0,207,0,0],["v","А сестра его в лачуге",0,208,0,0],["v","Изнывает: в доме отчем",0,209,0,0],["v","Для нее угла не стало.",0,210,0,1],["v","Там на крови незамытой…",0,210,0,0],["v","Мать с любовником пирует…",0,211,0,0],["sp","Корифей"],["v","Для эллинов и для семьи твоей",0,212,0,0],["v","Немало бед пошло от Тиндариды,",0,213,0,0],["v","А теткою доводится тебе…<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,214,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","увидев <span class=\"ch\" data-ch=\"orest\">Ореста</span> и Пилада"],["v","О, не до слез нам, девушки, глядите,",0,215,0,0],["v","Глядите: там чужие… Вот они,<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,216,0,0],["v","Вот, вот они… На нас… В засаде были.",0,217,0,0],["v","Бегите же, скрывайтесь, я — домой…",0,218,0,0],["v","О, да спасут нас ноги от злодеев!..",0,219,0,0],["act","Действие первое","a2","I"],["scene","Явление шестое","s6",2,6],["sd","Электра, <span class=\"ch\" data-ch=\"orest\">Орест</span> и Пилад <span class=\"ch\" data-ch=\"orest\">Орест</span> преграждает ей дверь. Пилад становится позади ее, свита окружает ее, а она бросается к алтарю. Девушки сначала бегут, а потом из любопытства останавливаются, видя, что их не преследуют."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Постой, дитя несчастное… не бойся…",0,220,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","обнимая алтарь"],["v","Феб-Аполлон! Спаси нас от убийц!",0,221,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","улыбаясь"],["v","О, для ножа я выбрал бы иного.",0,222,0,0],["sd","(Хочет взять ее за руку.)"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Прочь… Не твоя, не трогай, говорят…",0,223,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","По праву я руки твоей касаюсь.",0,224,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","А меч зачем? Засада для чего?",0,225,0,0],["sd","(Хочет уйти.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, не беги, скажу — и вмиг поверишь.",0,226,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","останавливается и не борется с ним"],["v","И так стою, коль силой не уйти.",0,227,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я прихожу к тебе послом от брата.",0,228,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","с живостью"],["v","О, дорогой! Он жив или убит?",0,229,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Жив, — чтоб открыть посольство доброй вестью.",0,230,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","кланяется"],["v","За эту речь всех благ тебе, посол!",0,231,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Обоим нам, обоим счастья, боги!",0,232,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Несчастный, где ж теперь его приют?",0,233,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Спроси-ка: где он бед не натерпелся!",0,234,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","По крайней мере, сыт ли он, скажи?",0,235,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не голоден, но жалок, как изгнанник.",0,236,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Сюда ж зачем тебя направил брат?",0,237,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Узнать, жива ли ты, легко ль живется?",0,238,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","протягивая руки"],["v","Скажи ж ему, как исхудала я…",0,239,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Морщины слез твоих пред ним оплачу…",0,240,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Про волосы скажи — скосила их.",0,240,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Терзал тебя, царевна, жребий брата?",0,241,0,0],["v","Убитого отца терзала тень?..",0,242,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Да, мир не даст уж мне людей дороже…",0,243,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А брату есть ли кто тебя милей?",0,244,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Мил, да далек… Здесь руку не протянет…",0,245,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","избегая продолжения разговора"],["v","В такую даль зачем ты забралась?",0,246,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Я замужем… О, легче бы в могилу…",0,247,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Жаль брата мне… Микенец, что ли, муж?",0,248,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","вздохнув"],["v","Да, о другом мечтал отец когда-то…",0,249,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но кто же он? Как брату передать?",0,250,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","указывая на лачугу"],["v","Вот дом его… да, от Микен не близко.",0,251,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","оглядывая лачугу"],["v","Дом пастуха иль пахаря приют.",0,252,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Муж захудал, но знатен — я в почете…",0,253,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","иронически"],["v","<span class=\"ch\" data-ch=\"elektra\">Электру</span> чтит супруг, ты говоришь?",0,254,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","На ложе он ее не посягает!",0,255,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что ж, дал обет иль брезгает женой?",0,256,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Нет, брака он не признает законным:",0,257,0,0],["v","В Эгисфе прав отца не признает…",0,258,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Так, так: его пугает месть <span class=\"ch\" data-ch=\"orest\">Ореста</span>?",0,260,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Отчасти да, но дух его высок.",0,261,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Достойный муж, награды муж достойный…",0,262,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Вот погоди — вернется с поля он…",0,263,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","погруженный в свои мысли"],["v","А мать, тебя носившая, молчала?",0,264,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","со злобой"],["v","Что дети ей, ей были бы мужья…",0,265,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но над тобой с чего ж Эгисф глумился?",0,266,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Он нищих мне велит плодить, Эгисф…",0,267,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А ты б могла дать мстителя Атриду.",0,268,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, мне за брак ответит он, постой…",0,269,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А знает он, что ты еще девица?",0,270,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Нет, от него, о гость, таимся мы.",0,270,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","указывая на хор"],["v","А эти нас не выдадут в Микенах?",0,271,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Шпионов нет — ты можешь говорить…",0,272,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","помолчав, как бы вскользь"],["v","Здесь, в Аргосе, есть дело для <span class=\"ch\" data-ch=\"orest\">Ореста</span>?",0,273,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Какой позор! И ты ответа ждешь?",0,274,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","несколько смущенный"],["v","С убийцами покончить способ нужен.",0,275,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль нет его? Убили же отца.",0,276,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты вместе с ним, с <span class=\"ch\" data-ch=\"orest\">Орестом</span>, мать, Электра,",0,277,0,0],["v","Родимую пошла бы убивать?",0,278,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","с живостью"],["v","Топор готов, и кровь отца не смыта.",0,279,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Смотри — я так и брату передам.",0,280,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Зарежу мать… А там казните дочку…",0,280,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О!",0,281,0,0],["v","О, если бы <span class=\"ch\" data-ch=\"orest\">Орест</span> тебе внимал.",0,282,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Увы! Его узнать я не могла бы.",0,283,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Немудрено. Вас развели детьми.",0,284,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Но есть один: он друг и помнит брата…",0,285,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Тот, что его еще ребенком спас?",0,286,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Да и отца взрастил, маститый старец…",0,287,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Могилою почтен ли твой отец?",0,288,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Как не почтен! Из дома в поле брошен.",0,289,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Увы, увы! Что говоришь, жена?",0,290,0,1],["v","Терзают нас и вчуже злые муки.",0,290,0,0],["v","Но если тяжек будет твой рассказ,",0,291,0,0],["v","Все ж передать его я должен брату.",0,292,0,0],["v","И если жалость не дана в удел",0,293,0,0],["v","Сердцам невежд, а только мудрым сердцем,",0,294,0,0],["v","То диво ли, что мы платить должны",0,295,0,0],["v","Страданием за чуткость состраданья…",0,296,0,0],["sp","Корифей"],["v","Желанием и я горю узнать:",0,297,0,0],["v","Мы из дворца имеем вести редко,",0,298,0,0],["v","И бедствия тревожат тайной ум.",0,299,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Приходится рассказывать — от друга",0,300,0,1],["v","Не смею я беды своей таить",0,300,0,0],["v","И тяжкой доли отчей. Но, посланник,",0,301,0,0],["v","Уста мои раскрывший, не укрой",0,302,0,0],["v","Из повести печальной от <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,303,0,0],["v","Ни слова, я молю, скажи: в каком",0,303,0,0],["v","Здесь пеплосе я сохну — муки нищей",0,304,0,0],["v","В лачуге после царского чертога,",0,305,0,0],["v","Все, все ему поведай, — я сама",0,306,0,0],["v","Вот это платье выткала, иначе",0,306,0,0],["v","Я голою осталась бы… Сама",0,307,0,0],["v","Кувшин ношу к источнику и плачу…",0,308,0,0],["v","Как, чистая, чуждаюсь жен, но путь",0,309,0,0],["v","И в хоровод девичий мне заказан,",0,310,0,1],["v","И праздников <span class=\"ch\" data-ch=\"elektra\">Электре</span> нет. Увы!",0,311,0,0],["v","Царь Кастор, некогда в мужья царевне",0,312,0,0],["v","Назначенный и кровный ей, теперь",0,313,0,0],["v","Меж звездами сияет там, в эфире.",0,314,0,0],["v","А над добычею троянской мать",0,315,0,0],["v","Ее царит, и перед троном жены",0,316,0,0],["v","Фригийские, добытые отцом,",0,317,0,0],["v","Блистают позолотою аграфов,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,318,0,0],["v","Где по стенам еще Атрида кровь",0,319,0,0],["v","Гноится и чернеет. Сам убийца",0,320,0,1],["v","Руками неомытыми схватил",0,321,0,0],["v","Отцовский жезл — он в колеснице ездит,",0,322,0,0],["v","В которой ездил царь, и как он горд!",0,323,0,0],["v","Никто не смей полить могилы царской,",0,324,0,0],["v","Украсить веткой миртовой… костер",0,325,0,0],["v","Вождя не видел жертвы, а могилу",0,326,0,0],["v","Тиран, вина пьяней, ногами топчет…",0,327,0,0],["v","И, камнями тревожа мрамор плит,",0,328,0,0],["v","Кричит вождю убийца: \"Где же сын твой?",0,330,0,1],["v","Что не идет твой прах оборонять?\"",0,330,0,0],["v","Все, все, молю тебя, поведай брату —",0,331,0,0],["v","За многих здесь язык мой говорит:",0,332,0,0],["v","За руки, и за губы, и за сердце,",0,333,0,0],["v","За стриженую голову, отца",0,334,0,0],["v","За имя славное… скажи: позором будет,",0,335,0,0],["v","Коль за царя, что Трою рушил, сын,",0,336,0,0],["v","Во цвете лет и крови благородной,",0,337,0,0],["v","С убийцею покончить не дерзнет.",0,338,0,0],["sp","Корифей"],["v","А вот и он, Электра, твой супруг:",0,339,0,0],["v","С посева, знать, домой идет на отдых.",0,340,0,1],["scene","Явление седьмое","s7",2,7],["sd","Те же и пахарь (слева) — он несет в руках упряжь."],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["dir","остановившись поодаль"],["v","Ба… это что за люди? Не пойму,",0,341,0,0],["v","Что привело их к сельскому порогу.",0,342,0,0],["v","Коль дело есть, не к ней же, (громко) и не след",0,343,0,0],["v","Простаивать замужней с молодежью.",0,344,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","с улыбкой идя ему навстречу"],["v","О дорогой! Так дурно о жене,",0,345,0,0],["v","Пожалуйста, не думай: эти люди",0,346,0,0],["v","Мне принесли Орестовы слова…",0,347,0,0],["sd","(<span class=\"ch\" data-ch=\"orest\">Оресту</span>.)"],["v","Прости мне, гость, смолчать я не умела.",0,348,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["dir","с живостью"],["v","Он жив и солнце видит, наш <span class=\"ch\" data-ch=\"orest\">Орест</span>?..",0,349,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Так говорят, и хочется мне верить…",0,350,0,1],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["v","А память зол семейных он хранит?..",0,351,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","В тумане, да, как нищий и скиталец…",0,352,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["v","Им что-нибудь велел он передать?",0,353,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Про бедствия мои прислал разведать.",0,354,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["dir","указывая на дом и на <span class=\"ch\" data-ch=\"elektra\">Электру</span>. Сдержанно"],["v","У них глаза, а у тебя язык…",0,355,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Уж знают все, расспросов их не бойся!",0,356,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["v","Так что ж во двор ворот не распахнешь?",0,357,0,0],["sd","(Открывает двери настежь и приглашает жестом царевичей.)"],["v","Прошу войти… за дорогие вести,",0,358,0,0],["v","Чем бог послал, мы рады угостить.",0,359,0,0],["sd","(Свите.)"],["v","Вы, спутники, несите в дом доспехи.",0,360,0,1],["sd","Свита не решается входить без знака <span class=\"ch\" data-ch=\"orest\">Ореста</span>."],["sd","(К <span class=\"ch\" data-ch=\"orest\">Оресту</span> и Пиладу.)"],["v","Не спорьте, нет: вы у меня в гостях…",0,360,0,0],["v","И этот дом, конечно, очень беден,",0,361,0,0],["v","Но к очагу зовут вас не рабы…",0,362,0,0],["sd","(С поклоном уходит в дом.)"],["scene","Явление восьмое","s8",2,8],["v","Те же без пахаря.",0,363,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","к <span class=\"ch\" data-ch=\"elektra\">Электре</span>"],["v","Так вот он, муж <span class=\"ch\" data-ch=\"elektra\">Электры</span> и союзник,",0,364,0,0],["v","Хранящий честь Атридовых детей…",0,365,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Да, это муж царевны горемычной.",0,365,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Узнай поди, какая кровь течет",0,366,0,0],["v","У человека в жилах, разберись",0,367,0,0],["v","В сердцах людей, средь этой ткани пестрой:",0,368,0,0],["v","В семье вельмож растет негодный сын,",0,369,0,0],["v","И добрые у злых выходят дети.",0,370,0,1],["v","Богач в душе пустыню обнажит,",0,371,0,0],["v","А светлый ум под рубищем таится.",0,372,0,0],["v","Чего-чего не наглядишься. Где ж",0,373,0,0],["v","И в чем искать мерила? Если в деньгах —",0,374,0,0],["v","Обманешься… И в бедности — загон:",0,375,0,0],["v","Нужда — плохой учитель. Средь военных?",0,376,0,0],["v","Но кто ж оценит доблесть их в бою?",0,377,0,0],["v","Свидетели там разве есть? Не проще ль",0,378,0,0],["v","Игру судьбы признать и покориться…",0,379,0,0],["v","Вот человек — ни власти у него,",0,380,0,1],["v","Ни родичей прославленных, и в мире",0,380,0,0],["v","Не прогремит молва о нем, — меж тем",0,381,0,0],["v","Найдется ли среди аргосцев лучший?",0,382,0,0],["v","О гордецы, оставите ль вы нас",0,382,0,0],["v","По знатности делить, забывши душу?",0,383,0,0],["v","Иль в жизни кровь, не мягкий нрав людей",0,384,0,0],["v","Достойными являет? Да, из добрых",0,385,0,0],["v","Хозяева и граждане, а те,",0,385,0,0],["v","Вельможами рожденные, не только ль",0,386,0,0],["v","Статуями на площадях стоять",0,387,0,0],["v","Прилично им? О силе рук, пожалуй,",0,387,0,0],["v","Подумаешь, чтоб подкрепить копье,",0,388,0,0],["v","И то не так — копье у храбрых метче…",0,389,0,0],["v","А храбрости душа приют дает…",0,390,0,1],["v","Но нас зовут войти… Гостеприимство<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,390,0,0],["v","Орестовых послов не оскорбит,",0,391,0,0],["v","И самого пославшего <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,392,0,0],["v","Оно бы не унизило… Рабы,",0,392,0,0],["v","Ступайте в дом.",0,393,0,0],["v","Рабы входят в ворота.",0,394,0,0],["v","У бедняка радушный",0,395,4,0],["v","Прием милей, чем ласки богача…",0,395,0,0],["sd","(<span class=\"ch\" data-ch=\"elektra\">Электре</span>.)"],["v","Мне нравится твой муж… Но как-то грустно,",0,396,0,0],["v","Что не <span class=\"ch\" data-ch=\"orest\">Орест</span> сегодня нас ведет",0,397,0,0],["v","На светлый пир в микенские чертоги…",0,397,0,0],["v","Дождемся ль мы? О да… Ведь Феба речь",0,398,0,0],["v","Не прозвучит бесследно… Не гаданье",0,399,0,0],["v","Из праздных уст его глагол святой.",0,400,0,1],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> и Пилад уходят в дом.",0,400,0,0],["scene","Явление девятое","s9",2,9],["sd","<span class=\"ch\" data-ch=\"elektra\">Электра</span> и пахарь, который выходит из дому после следующих слов корифея."],["sp","Корифей"],["v","О, радуйся ж, Электра… будто солнце",0,401,0,0],["v","Зимой из туч пригрело нас, судьба",0,402,0,0],["v","Твоя чуть-чуть, но к благу изменилась.",0,403,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","с сердцем к мужу"],["v","Ты потерял рассудок — из углов",0,404,0,0],["v","Нужда глядит, а он — вельмож к обеду.",0,405,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["v","О, если вид их души отразил,",0,406,0,0],["v","Над нищетой они не посмеются.",0,407,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","несколько успокоенная"],["v","Назвать назвал, а только как же их",0,408,0,0],["v","Накормим мы? К отцовскому кормильцу",0,409,0,0],["v","Ступай скорей. Живет он на Танае,<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,410,0,1],["v","Который, через Аргос пробежав,",0,411,0,0],["v","Спартанские пределы орошает.",0,412,0,0],["v","Приход гостей поведав старику,",0,413,0,0],["v","Ты на обед проси припасов… Боги,",0,414,0,0],["v","Как будет рад узнать он от тебя,",0,415,0,0],["v","Что жив <span class=\"ch\" data-ch=\"orest\">Орест</span>, когда-то им спасенный.",0,416,0,0],["v","К царице ж нам теперь заказан путь:",0,417,0,0],["v","Иль, горестной внимая вести, стала б",0,418,0,0],["v","Она послов <span class=\"ch\" data-ch=\"orest\">Ореста</span> угощать?..",0,419,0,0],["sp","<span class=\"ch\" data-ch=\"pahar\">Пахарь</span>"],["v","Изволь, изволь. От старого ни слова",0,420,0,1],["v","Не утаю… Ты ж по углам пошарь,",0,421,0,0],["v","Сготовь, что есть. В нужде ль не извернется",0,422,0,0],["v","Хорошая хозяйка? Ведь гостям",0,423,0,0],["v","Насытиться бы только на сегодня —",0,424,0,0],["v","Уж будто ты и хлеба не найдешь?",0,425,0,0],["v","Порассудить, так деньги нам потребны",0,426,0,0],["v","На два конца: принять друзей да их",0,427,0,0],["v","Врачам платить, коль занемогут. Точно,",0,428,0,0],["v","Без денег здесь беда. А сытым быть",0,429,0,0],["v","И завтра и сегодня может всякий,",0,430,0,1],["v","И за двоих богач едва ли съест.",0,431,0,0],["v","Уходят: пахарь в поле, <span class=\"ch\" data-ch=\"elektra\">Электра</span> в дом.",0,432,0,0],["scene","Первый музыкальный антракт","s10",2,10],["sp","Хор"],["str","Строфа I"],["v","Славой горды, когда-то триеры во Трое",0,433,0,0],["v","Мириадами плещущих весел",0,434,0,0],["v","В вихорь пляски морских увлекали нимф,",0,435,0,0],["v","А меж них, очарованный",0,436,0,0],["v","Трелью флейты, дельфин играл,<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,437,0,0],["v","Вияся меж синих…",0,438,0,0],["v","Он за сыном Фетиды плыл,",0,439,0,0],["v","Что с Атридом-царем к Илиону,",0,440,0,1],["v","Бурь соперник, направил бег",0,440,0,0],["v","К шумным волнам Симунта.<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,441,0,0],["str","Антистрофа I"],["v","В оны дни из Евбеи богини моря",0,442,0,0],["v","С наковальни Гефеста златой",0,443,0,0],["v","Дивный труд оружейный, любя, несли",0,444,0,0],["v","Через Пелий, чрез горных глубь",0,445,0,0],["v","Славной Оссы святых долин,",0,446,0,0],["v","Чрез выси нагие,",0,447,0,0],["v","Меж тенями скиталиц нимф,",0,448,0,0],["v","В край, где вырастил конник Пелей",0,449,0,0],["v","Славу эллинов, чадо волн",0,450,0,1],["v","И соперника вихрей…",0,451,0,0],["str","Строфа II"],["v","Щит твой, о сын Нереиды, навплиец, в гавани бывший,<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,452,0,0],["v","Восторгом объят,",0,453,0,0],["v","Речью такой мне прославил:",0,454,0,0],["v","Дивный свод окружали там",0,455,0,0],["v","Образы, ужасом сердце хитро наполняя:",0,456,0,0],["v","В ободе, щит обегающем,",0,457,0,0],["v","Голову срезав Горгоне лютой,",0,458,0,0],["v","На окрыленных стопах Персей",0,459,0,0],["v","Морем летел, с ним и Гермес, Майи рожденье,",0,460,0,0],["v","Нив плодородных хранитель дивный.",0,461,0,0],["str","Антистрофа II"],["v","А посредине щита, ослепляя, сиял",0,462,0,0],["v","Гелий ликом лучистым,",0,463,0,0],["v","Быстрых коней владыка…",0,464,0,0],["v","Там кружили созвездия",0,465,0,0],["v","Ярких Гиад и Плеяд, Приамида сразивших.<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,470,0,1],["v","Шлем же златой его сфинксами",0,471,0,0],["v","Так и горел, и в когтях у вещих",0,472,0,0],["v","Билась добыча, а грудь ему",0,473,0,0],["v","Лев украшал, что за дивно крылатым конем",0,474,0,0],["v","Огненным взором следил так жадно.<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,475,0,0],["str","Эпод"],["v","Древко копья его хищного быстрые красили кони,",0,476,0,0],["v","И черный прах вокруг летел…",0,477,0,0],["v","Таких бойцов владыку ты,",0,478,0,0],["v","Тиндарова дочь, о злая жена, решилась убить.",0,480,0,1],["v","Но смерть и тебе суждена",0,481,0,0],["v","Бессмертными, и я когда-нибудь",0,482,0,0],["v","В твоей груди увижу меч тяжелый,",0,483,0,0],["v","Облитый кровью мщенья…",0,484,0,0],["act","Действие второе","a3","II"],["scene","Явление десятое","s11",3,11],["sd","Старик с ягненком и корзиной (справа), вскоре затем <span class=\"ch\" data-ch=\"elektra\">Электра</span>."],["sp","Старик"],["v","Где, где ж она, царевна молодая,",0,485,0,0],["v","Юница — дочь великого царя,<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,486,0,0],["v","Которого ребенком я лелеял,",0,487,0,0],["v","Увы, давно…",0,488,0,0],["v","О, как тяжел подъем",1,488,0,0],["v","К ее жилью для дряхлых ног, а все же",0,490,0,1],["v","Дрожащие колени старый горб",0,490,0,0],["v","К друзьям несут…",0,491,0,0],["sd","(Медленно подходит к дому <span class=\"ch\" data-ch=\"elektra\">Электры</span> и видит ее стоящую на пороге.)"],["v","О дочь моя, ягненка",0,492,4,0],["v","Отборного я из-под матки взял",0,493,0,0],["sd","(ставит корзину и вынимает из нее провизию)"],["v","Вам на обед, вот пироги в корзине,",0,494,0,0],["sd","(доставая из-за спины мех)"],["v","И цвет сыров, и Вакха старый дар.",0,495,0,0],["v","Немного здесь его осталось, правда,",0,496,0,0],["v","Но если им домашнее вино",0,497,0,0],["v","Заправишь ты, то дивным ароматом",0,498,0,0],["v","Оно сердца гостей твоих пленит.",0,499,0,0],["v","Иди же, стол уставь дарами старца,",0,500,0,1],["sd","<span class=\"ch\" data-ch=\"elektra\">Электра</span> хочет идти, но видит слезы старика и останавливается."],["v","А у меня так слезы и бегут,",0,500,0,0],["v","И край плаща за ними не поспеет…",0,501,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О старый друг! Росою слез, скажи,",0,502,0,0],["v","Какая скорбь лицо твое покрыла?",0,503,0,0],["v","Скорбишь ли ты, что после долгих дней",0,503,0,0],["v","Меня узрел и в рубище и в муках?",0,504,0,0],["v","О брате ли изгнаннике скорбишь?",0,505,0,0],["v","Иль об отце, которого баюкал",0,506,0,0],["v","Ты для себя и для друзей напрасно?",0,506,0,0],["sp","Старик"],["v","Напрасно, но смирился и молчу…",0,507,0,0],["v","Лишь нынче я, с пути свернув, к могиле",0,508,0,0],["v","Хотел припасть и, благо глаз вокруг",0,509,0,0],["v","Там не было, поплакать на свободе,",0,510,0,1],["v","И только что из меха, где гостям",0,510,0,0],["v","Я нес вино, свершил я возлиянье",0,511,0,0],["v","И миртом гроб Атрида увенчал…",0,512,0,0],["v","Как в очи мне овечья кровь мелькнула,",0,513,0,0],["v","Пролитая недавно, и волос",0,514,0,0],["v","Отрезанный, и золотистый локон…",0,515,0,0],["v","И подивился я, ужели кто",0,516,0,0],["v","Из Аргоса прийти дерзнул к могиле?",0,517,0,0],["v","Не может быть… Иль прах отца почтить",0,518,0,0],["v","Сюда твой брат явился гостем тайным?",0,519,0,0],["sd","(Приостанавливается.)"],["sd","<span class=\"ch\" data-ch=\"elektra\">Электра</span> вскидывает на него глаза, потом глубоко задумывается."],["v","Вот эта прядь.",0,520,2,1],["sd","(Подает ей золотой локон, развернув его.)"],["sd","<span class=\"ch\" data-ch=\"elektra\">Электра</span> молча и внимательно рассматривает его, не думая сравнивать со своими."],["v","Прикинь ее к своим:",1,520,0,0],["v","Подходит ли по цвету — с кровью отчей",0,521,0,0],["v","Подобие вселяется в детей…",0,522,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","отстраняет его руку"],["v","Из мудрых уст такие речи странны.",0,523,0,0],["v","Иль думаешь, что мой отважный брат",0,524,0,0],["v","Здесь прятаться бы вздумал от Эгисфа?..",0,525,0,0],["v","А эта прядь? Да разве цвет волос",0,526,0,0],["v","Царевича, возросшего в палестре,",0,527,0,0],["v","И нежный цвет взлелеянных гребнем",0,528,0,0],["v","Девичьих кос сберечь могли бы сходство?",0,530,0,1],["v","Иль не роднит и кровью чуждых масть?",0,531,0,0],["v","Нет, локоном почтил его могилу,",0,545,0,1],["v","Конечно, кто-нибудь заезжий, а не то",0,541,0,0],["v","Украдкою аргосец помолился.",0,537,0,0],["sp","Старик"],["v","А если след сандалии сравнить",0,532,0,1],["v","С твоей ногой, дитя, найдем ли сходство?",0,532,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","На камне след? Что говоришь, старик?",0,533,0,0],["v","Да если б след его и оставался,",0,534,0,0],["v","Неужто же у брата и сестры",0,535,0,0],["v","Подобиться размером ноги могут?",0,536,0,0],["sp","Старик"],["v","Скажи еще: работу детских рук,",0,537,0,0],["v","Узнаешь ли Орестову одежду,",0,538,0,0],["v","Которую ты выткала ему",0,539,0,0],["v","Пред тем, как мне нести его в Фокиду?",0,540,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль бредишь ты? Да ведь тогда, старик,",0,541,0,0],["v","Ребенком я была: хламиду эту",0,542,0,0],["v","Неужто брат наденет и теперь?",0,543,0,0],["v","Иль, может быть, растут одежды с нами?<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,544,0,1],["sp","Старик"],["dir","продолжает в том же спокойном тоне"],["v","А гости где? Мне повидать бы их",0,547,0,1],["v","И расспросить хотелось об <span class=\"ch\" data-ch=\"orest\">Оресте</span>.",0,547,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","заглядывая во двор"],["v","Они идут сюда… и спешен шаг…",0,548,0,0],["scene","Явление одиннадцатое","s12",3,12],["v","Те же и <span class=\"ch\" data-ch=\"orest\">Орест</span> и Пилад со свитой.",0,549,0,0],["sp","Старик"],["dir","про себя"],["v","Вельможи, да. Но разве не бывает,",0,550,0,1],["v","Что он и князь, а низкая душа?",0,550,0,0],["sd","(Громко, кланяясь.)"],["v","А все-таки — привет вам, чужестранцы.",0,551,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","оглянувшись на старика"],["v","Здорово, дед.",0,552,0,0],["sd","(К <span class=\"ch\" data-ch=\"elektra\">Электре</span>.)"],["v","Какого друга тень",0,553,4,0],["v","Перед тобой, царевна, этот дряхлый?",0,554,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Он вынянчил отца <span class=\"ch\" data-ch=\"elektra\">Электры</span>, гость.",0,555,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что говоришь? И сохранил <span class=\"ch\" data-ch=\"orest\">Ореста</span>?",0,555,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Когда-то да, не знаю, как теперь…",0,556,0,0],["sd","Старик между тем пристально всматривается в <span class=\"ch\" data-ch=\"orest\">Ореста</span>."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ба!..",0,557,0,0],["v","Он глаз с меня не сводит, как с монеты",0,558,0,0],["v","Сверкающей… Похож я на кого?",0,559,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ты люб ему, мой гость, как сверстник брата.",0,560,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["sd","И друг его… (Указывая ей на старика, который обходит его с внимательным осмотром.) Он пляшет вкруг меня."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","покачивая головой, вполголоса"],["v","Дивлюсь сама, что сделалось со старым.",0,561,0,0],["sp","Старик"],["dir","останавливаясь и громко"],["v","Царевна, дочь моя, молись, молись…",0,562,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","А за кого молиться: за отшедших",0,563,0,0],["v","Иль за живых молиться мне, старик?",0,564,0,0],["sp","Старик"],["v","Сокровище тебе послали боги.",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","воздевая руки к небу"],["v","Я им молюсь… Но только за кого?",0,566,0,0],["sp","Старик"],["dir","тихо, трогая <span class=\"ch\" data-ch=\"orest\">Ореста</span> за руку"],["v","Вот за кого: он твой желанный друг.",0,567,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","<span class=\"ch\" data-ch=\"orest\">Оресту</span>"],["v","Боялась я давно, что он помешан.",0,568,0,0],["sp","Старик"],["dir","с живостью"],["v","Помешан я? Иль это не <span class=\"ch\" data-ch=\"orest\">Орест</span>?",0,569,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Старик, зачем будить надежду в сердце?",0,570,0,1],["sp","Старик"],["dir","торжественно"],["v","Перед тобой Агамемнонов сын…",0,570,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Но признаки… Иначе… Как поверю?",0,571,0,0],["sp","Старик"],["v","А этот шрам над бровью?",0,572,0,0],["v","<span class=\"ch\" data-ch=\"elektra\">Электра</span> всматривается в лицо <span class=\"ch\" data-ch=\"orest\">Оресту</span>.",0,572,0,0],["v","Помнишь, вы",0,573,4,0],["v","За телкою гонялись и, свалившись,",0,574,0,0],["v","Он бровь ссадил. Ты видишь этот знак?",0,575,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","Несколько секунд улыбка воспоминания бродит по лицу <span class=\"ch\" data-ch=\"elektra\">Электры</span>, В промежутках она бросает на <span class=\"ch\" data-ch=\"orest\">Ореста</span> быстрые взгляды"],["v","Ты бредишь… Шрам?.. О нет… О да, о да!",0,575,0,0],["sd","(Расцветает улыбкою.)"],["sp","Старик"],["v","И медлишь ты обнять его, Электра?",0,576,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, больше нет, старик: ведь это ж брат…",0,577,0,0],["v","О, как мне сладко верить!",0,577,0,0],["sd","(Обнимая <span class=\"ch\" data-ch=\"orest\">Ореста</span>.)"],["v","Мой желанный,",0,578,4,0],["v","Ты здесь? Ты здесь?",0,579,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","отвечая ей"],["v","И наконец с сестрой.",1,579,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ждала ли я?",0,580,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Мечтал ли я, скиталец?",1,580,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ты, ты — Орест?..",0,581,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Единый мститель твой.",1,581,0,0],["v","И только бы не оборвалась петля,",0,582,0,0],["v","Не дрогну я, — коль боги не обман,",0,583,0,0],["v","А истина не под пятой обиды.",0,584,0,0],["v","Разгорается жаркий полдень.",0,585,0,0],["sp","Хор"],["v","Загорелся ты, о желанный день!",0,586,0,0],["v","Как сигнал в ночи, ярким пламенем",0,587,0,0],["v","Далеко летишь… Из изгнания",0,588,0,0],["v","Он, блуждая, пришел…",0,589,0,0],["v","Это бог, это бог нам победу опять",0,590,0,1],["v","Подает, сестра,",0,590,0,0],["v","К небу вы, персты… В небеса — уста!..",0,591,0,0],["v","О, молись со мной, чтобы счастливо",0,592,0,0],["v","Для тебя вступил в отчий город брат…",0,593,0,0],["v","Во время песни хора <span class=\"ch\" data-ch=\"elektra\">Электра</span> ласкает брата.",0,594,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","мягко отстраняясь"],["v","Ну, будет же!..",0,595,0,0],["v","Как нежны вы, объятья!",1,595,0,0],["v","Но разве нас опять разлука ждет?..",0,596,0,0],["v","А ты, старик, ты, благо здесь, советом",0,597,0,0],["v","Наставь меня злодею отомстить",0,598,0,0],["v","Отцовскому и матери, его",0,599,0,0],["v","Союзнице на ложе нечестивом.",0,600,0,1],["v","Хоть несколько осталось ли, скажи,",0,600,0,0],["v","У нас друзей среди аргосцев? Или",0,601,0,0],["v","За златом вслед исчезли и друзья?..",0,602,0,0],["v","Кого ж возьму в союзники, и ночью",0,603,0,0],["v","Иль днем, и как проникнуть во дворец?",0,604,0,0],["sp","Старик"],["v","Дитя мое, у бедного <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,605,0,0],["v","Здесь нет друзей. И часты ли они,",0,605,0,0],["v","Друзья пиров, делящие невзгоду?..",0,606,0,0],["v","Ты разорен дотла, ты понял, — зги",0,607,0,0],["v","Надежды нам, твоим последним верным,",0,608,0,0],["v","Во тьме невзгод твоих не различить.",0,609,0,0],["v","Остались нам рука с мечом и жребий,",0,610,0,1],["v","Лишь в них твоя отчизна и престол.",0,611,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, цель ясна… Но средства, старец, средства.",0,612,0,0],["sp","Старик"],["v","Два трупа — мать с Эгисфом, и конец…",0,613,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Победный лавр… Но как его добьешься?",0,614,0,0],["sp","Старик"],["v","Ну, во дворце трудненько, это так.",0,615,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Охрана там надежная — все копья?",0,616,0,0],["sp","Старик"],["v","Да, трусит он. И по ночам не спит…",0,617,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Так, так… Еще сообрази, подумай…",0,618,0,0],["sd","Пауза."],["sp","Старик"],["v","Не знаю, что и вздумать… разве… вот…",0,619,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Тебе — совет, а мне бы — разуменье…",0,620,0,1],["sp","Старик"],["v","Эгисфа я, как шел сюда, видал…",0,621,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Известие приятное… далеко?",0,622,0,0],["sp","Старик"],["v","Близ здешних нив, на пастбище коней.",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что делал он? Мелькает луч надежды.",0,624,0,0],["sp","Старик"],["v","В честь нимф Эгисф готовил торжество.",0,625,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Благословить в утробе плод иль чадо?",0,626,0,0],["sp","Старик"],["v","Не знаю… Я видал коров и нож…",0,627,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Велик ли был отряд, иль только слуги?",0,628,0,0],["sp","Старик"],["v","Чужие все… аргосцев ни души.",0,629,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Как думаешь: меня бы не узнали?",0,630,0,1],["sp","Старик"],["v","Из них никто тебя и не видал.",0,631,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А, в случае победы, челядь — наша?",0,632,0,0],["sp","Старик"],["v","Ты счастлив — да: где сила, там и раб.",0,633,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А как бы мне к Эгисфу подобраться?",0,634,0,0],["sp","Старик"],["v","Ну, раз-другой в глаза ему метнись.",0,635,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А далеко ль от нив его дорога?..",0,636,0,0],["sp","Старик"],["v","О, зов на пир до слуха долетит.",0,637,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","На горький пир, коли богам угодно.",0,638,0,0],["sp","Старик"],["v","Как дальше быть, увидишь сам, Орест…",0,639,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Спасибо, дед. Но где же мать найду я?",0,640,0,1],["sp","Старик"],["v","Та в Аргосе… Лишь под вечер — на пир…",0,641,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что ж так, старик, зачем не вместе с мужем?",0,642,0,0],["sp","Старик"],["v","Глумления аргосского бежит.",0,643,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ее клянут, и это ей известно?..",0,644,0,0],["sp","Старик"],["v","А что же, их, безбожных, прославлять?",0,645,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но как же мне убить обоих разом?..",0,646,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Оставь мне мать: я заманю ее.",0,647,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","С Эгисфом же я и один покончу.",0,648,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Пусть даст судьба обоим отомстить.",0,649,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да будет так. Но в чем твой план, скажи мне.",0,650,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ступай сейчас к царице во дворец.",0,650,0,0],["sd","⟨Старик"],["v","Иль передать что надо Тиндариде?⟩",0,651,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Скажи, что ей я внука родила.",0,652,0,0],["sp","Старик"],["v","А как давно? Иль только что, царевна?",0,653,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Десятый день, день жертвы и молитв…",0,654,0,0],["sp","Старик"],["v","Но где ж тут смерть? мне невдомек, Электра!",0,655,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль дочь она поздравить не придет?",0,656,0,0],["sp","Старик"],["v","О бедная, ты ль у царицы в думах?",0,657,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","со злобой"],["v","Поплачем с ней над долею внучат…",0,658,0,0],["sp","Старик"],["v","Ну, может быть… Но где же мета? Ты сбилась…<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,659,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","со смехом"],["v","Тут будет ей, проклятой, и конец…",0,660,0,1],["sp","Старик"],["v","Я не пойму. Ну, за ворота ступит…",0,661,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль в адские их долго обратить?",0,662,0,0],["sp","Старик"],["dir","мечтательно"],["v","Глаза смежить, насытив пиром мести!",0,663,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Скорей же путь рассказывай ему…",0,664,0,0],["sp","Старик"],["v","Туда, где жрец готовит нимфам телку?",0,665,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","А слов моих царице не забыл?",0,666,0,0],["sp","Старик"],["v","Так передам — сама не скажешь лучше…",0,667,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Смелее, брат! Начало за тобой.",0,668,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ну, проводник! Готовы, собирайся!..",0,669,0,0],["sp","Старик"],["v","Не откажусь… и рад, что мы идем…",0,670,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О Зевс, о бог отцов моих и кара",0,670,0,0],["v","Врагов отца! Уныл наш жребий, сжалься!",0,671,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Нас, кровь свою, Зевес, ты пожалей!",0,672,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Владычица микенских алтарей,",0,673,0,0],["v","Коль правы мы, дай нам победу, Гера.",0,674,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","И отомстить за кровь отца позволь…",0,675,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О наш отец, подземный мрак узревший,",0,676,0,0],["v","Несчастием убитый, о земля —",0,677,0,0],["v","Владычица, к тебе простерты длани,",0,678,0,0],["v","Спаси детей царя — он нас любил.",0,679,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Отец, с собой товарищей похода",0,680,0,1],["v","Фригийского зови к нам, если спят",0,680,0,0],["v","Они в гробах, всех тех веди, которым",0,681,0,0],["v","Безбожный враг здесь сердце отравил…",0,682,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты слышишь нас, о жертва Тиндариды?<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,683,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Все слышит он.<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,684,0,0],["v","Пора, пора, Орест!",1,684,0,0],["v","Срази ж его. Рыдая, умоляю:",0,685,0,0],["v","Не промахнись, царевич. Если ж бой",0,686,0,0],["v","Тебя пожрет, не думай, что останусь",0,687,0,0],["v","Я жить. С мечом двуострым в сердце разве!",0,688,0,0],["v","⟨Домой пойду и меч я приготовлю.",0,689,0,0],["v","Коль от тебя счастливой будет весть,",0,690,0,1],["v","Весь дом наполнят радостные вопли.",0,690,0,0],["v","Погибнешь ты — и я погибну вслед.",0,691,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я знаю все.",0,692,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Мужайся — и за дело!⟩",1,692,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> уходит с Пиладом, стариком и свитою,",0,693,0,0],["sd","(Хору)"],["v","Вы, женщины, как загорится бой,",0,693,0,0],["v","Мне дайте знать. С железом и готова,",0,694,0,0],["v","Я буду вся — одно вниманье, жены.",0,695,0,0],["v","И если труп <span class=\"ch\" data-ch=\"orest\">Орестов</span> подберут",0,696,0,0],["v","Его враги, не дожидаясь мести,",0,696,0,0],["v","Я, мертвая, глумленья их приму.",0,697,0,0],["sd","(Уходит.)"],["scene","Второй музыкальный антракт","s13",3,13],["str","Строфа I"],["v","Эту сказку заводит седая молва…",0,698,0,0],["v","Как у матери нежной восславил плод",0,699,0,0],["v","Там, на высях аргосских,",0,700,0,1],["v","Пан, хранитель полей и царь",0,701,0,0],["v","Дивно слаженной флейты.",0,702,0,0],["v","Сладким пеньем и пляской прославлен был",0,703,0,0],["v","Златорунный ягненок.",0,704,0,0],["v","Чу… постой… С выси мраморной вдаль летит",0,705,0,0],["v","Зычный вестника голос:",0,706,0,0],["v","\"Все на площадь, живей, живей!",0,707,0,0],["v","И любуйся, микенский люд,",0,708,0,0],["v","На добычу владык своих,",0,710,0,1],["v","Грозно-дивное знаменье\".",0,710,0,0],["v","Славят люди дворец царя,",0,711,0,0],["v","И весельем горит чертог.",0,712,0,0],["str","Антистрофа I"],["v","Эту сказку мне шепчет седая молва:",0,713,0,0],["v","Распахнулась, сияя, там храмов высь,",0,714,0,0],["v","И алтарное ярче",0,715,0,0],["v","Будто вспыхнуло пламя вмиг…",0,715,0,0],["v","Флейта, Музы рабыня,",0,716,0,0],["v","Лучших песен своих не жалела нам",0,717,0,0],["v","В честь руна золотого.",0,718,0,0],["v","Не дремал той порою Фиестов чертог:",0,719,0,0],["v","К ложу тайных объятий",0,720,0,1],["v","Он Атрея жену манит,",0,721,0,0],["v","С ней и диво к себе влечет,",0,722,0,0],["v","Золотого ягненка, царь.",0,723,0,0],["v","И вернулся да гражданам",0,724,0,0],["v","Так кричит: \"У меня теперь",0,725,0,0],["v","Наших гор златорунный цвет\".",0,726,0,0],["str","Строфа II"],["v","И светил золотые пути",0,727,0,0],["v","В этот миг Кронид передвинул,",0,728,0,0],["v","Жгучий блеск передвинул солнца",0,729,0,0],["v","И зари мерцающий лик.",0,730,0,1],["v","И на юг, по склонам небесным,",0,731,0,0],["v","Дивно пламенный зной потек,",0,732,0,0],["v","А к Медведице влажные тучи",0,733,0,0],["v","Потянулись. Палим с тех пор,",0,734,0,0],["v","Изнывает от жажды трон Аммона",0,735,0,0],["v","Без отрады Зевсовых ливней.<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,736,0,0],["str","Антистрофа II"],["v","Так молва говорит, но словам",0,737,0,0],["v","Этой сказки мало я верю.",0,738,0,0],["v","Что мы ей, колеснице бога?",0,739,0,0],["v","И неужто покинет путь,",0,740,0,1],["v","Чтобы люди мукой платили",0,740,0,0],["v","За обиду других людей?",0,741,0,0],["v","Страха божия ради сложила",0,742,0,0],["v","Эту сказку молва в миру,",0,743,0,0],["v","Но, забыв ее, мужа убила ты,",0,744,0,0],["v","О сестра прославленных братьев!<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,745,0,0],["act","Действие третье","a4","III"],["scene","Явление двенадцатое","s14",4,14],["sd","После первых слов корифея из дому выходит <span class=\"ch\" data-ch=\"elektra\">Электра</span> с ножом. За сценой стоны."],["sp","Корифей"],["v","Но тише, тише, чу…",0,745,0,0],["v","Вы слышите ль, подруги, странный шум?",0,746,0,0],["v","Иль у меня в ушах гудит?.. Но будто",0,747,0,0],["v","Подземный гром… раскатами. Ясней,",0,748,0,0],["v","Ясней теперь… Там кто-то дышит… стоны",0,749,0,0],["v","Вздымаются… Сюда, сюда, царевна!..",0,750,0,1],["sd","Входит <span class=\"ch\" data-ch=\"elektra\">Электра</span>."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Я вам нужна, иль уж окончен бой?",0,751,0,0],["sp","Корифей"],["v","Кровавому стенанию мы внемлем…",0,752,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","прислушивается"],["v","Да, это стон… Далекий, — все же стон…",0,753,0,0],["sp","Корифей"],["v","Не близок путь, но как он ясен, слышишь?",0,754,0,0],["sd","(Прилегает к земле, стоны продолжаются.)"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","А стонет друг иль чуждые уста?",0,755,0,0],["sp","Корифей"],["v","Не разберешь… на все лады там стонут…",0,756,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Чего ж я жду… Иль нож мой не готов?",0,757,0,0],["sd","(Заносит над горлом меч. Корифей удерживает ее руку.)"],["sp","Корифей"],["v","Остановись… Еще не ясен жребий.",0,758,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> разбит — оттуда нет гонцов.",0,759,0,0],["sp","Корифей"],["v","Не птицы же. Иль так им царь и сдался?",0,760,0,1],["scene","Явление тринадцатое","s15",4,15],["sd","Те же и вестник (с той же стороны, откуда приходили стоны)."],["sp","Вестник"],["v","О славные микенские юницы!",0,761,0,0],["v","Победы весть Орестовой несу…",0,762,0,0],["v","Там на земле лежит цареубийца",0,763,0,0],["v","Эгисф, богам молитесь — он убит.",0,764,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","с некоторым недоверием"],["v","Но кто же ты? И как тебе поверю?",0,765,0,0],["sp","Вестник"],["v","Я в свите был у брата твоего.",0,766,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Прости мне, друг… От ужаса и память",0,767,0,0],["v","Изменит нам. Я узнаю теперь",0,768,0,0],["v","Твое лицо… Итак — злодея нет…",0,769,0,0],["sp","Вестник"],["v","В живых… Вели — и повторю: он умер…",0,770,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, зоркая, о, правда… Наконец!",0,770,0,0],["v","Но расскажи мне самый ход убийства,",0,771,0,0],["v","Ты каждый шаг поведай нам, гонец.",0,772,0,0],["sp","Вестник"],["v","Стопы подъяв от этого порога,",0,773,0,0],["v","Вступили мы на двухколейный путь",0,774,0,0],["v","И славного микенского владыку",0,775,0,0],["v","Увидели. Он по саду гулял",0,775,0,0],["v","Среди ручьев, срезая ветки мирта,",0,776,0,0],["v","Чтобы венок потом из нежных свить.",0,777,0,0],["v","Увидел нас и говорит: \"Привет вам,",0,778,0,0],["v","О путники, откуда вы и путь",0,779,0,0],["v","К какой земле направили?\" А брат твой",0,780,0,1],["v","Ему в ответ: \"Фессалия нас шлет",0,781,0,0],["v","На берега Алфея, к Олимпийцу,<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,782,0,0],["v","Отцу богов, с дарами мы идем…\"",0,783,0,0],["v","Эгисф опять: \"Ко мне прошу сегодня",0,784,0,0],["v","На светлый пир — я нимфам заколоть",0,785,0,0],["v","Тельца веду, а завтра, встав с зарею,",0,786,0,0],["v","Вы можете ускорить шаг. Войдем\".",0,787,0,0],["v","И стал он нас упрашивать — проходу",0,788,0,0],["v","Нам не давал, — а как в чертог привел,",0,790,0,1],["v","Кричит: \"Скорей подайте им умыться,",0,790,0,0],["v","Близ алтаря поставлю я гостей\".",0,791,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> ему на это: \"Мы проточной",0,792,0,0],["v","Струей реки уж умывались, царь,",0,793,0,0],["v","Но если нам с аргосцами прикажешь",0,794,0,0],["v","Тебе помочь при жертве, то опять",0,795,0,0],["v","Очиститься не откажусь, конечно\".",0,796,0,0],["v","Но разговор был прерван. Отложив",0,797,0,0],["v","Оружие, телохранитель царский",0,798,0,0],["v","И раб его — за дело все гурьбой…",0,799,0,0],["v","Кто нес фиал для крови, кто кошницы",0,800,0,1],["v","Священных круп, а там, на очаге,",0,800,0,0],["v","Раздув огонь, кувшины расставляли.",0,801,0,0],["v","Чертог гудел… Но вот, крупы твой отчим",0,802,0,0],["v","На жертвенник подбросив, возгласил:",0,803,0,0],["v","\"О нимфы скал, пускай не раз мне жертву",0,804,0,0],["v","Здесь приносить и, счастьем увенчав",0,805,0,0],["v","Главу царя с царицей Тиндаридой,",0,806,0,0],["v","Врагов его казните!\" — он тебя",0,807,0,0],["v","Здесь разумел с <span class=\"ch\" data-ch=\"orest\">Орестом</span>. А царевич,",0,808,0,0],["v","Тот шепотом молился, чтоб ему",0,809,0,0],["v","Отцовский дом вернуть.",0,810,0,1],["v","И нож, нащупав",1,810,0,0],["v","В кошнице, взял Эгисф: он тельчий волос",0,810,0,0],["v","Десницею в огонь священный вверг…",0,811,0,0],["v","И заколол распяленную жертву",0,812,0,0],["v","В руках рабов, державших ноги ей…",0,813,0,0],["v","И вновь тогда взывает он к <span class=\"ch\" data-ch=\"orest\">Оресту</span>:",0,814,0,0],["v","\"Средь доблестей в Фессалии у вас,",0,815,0,0],["v","Я слышал, два искусства процветают:",0,815,0,0],["v","Там мастера вы туши разнимать",0,816,0,0],["v","Да на коня узду накинуть ловки,",0,817,0,0],["v","Не откажи уверить в первом нас\".",0,818,0,0],["v","И вот в руках <span class=\"ch\" data-ch=\"orest\">Ореста</span> нож дорийский.",0,819,0,0],["v","Вмиг сорван с плеч его красивый плащ",0,820,0,1],["v","С аграфами; в подручные — Пилада,",0,820,0,0],["v","А челядь прочь; вот ногу захватил",0,821,0,0],["v","Он тельчую и, напрягая мускул,",0,822,0,0],["v","Глядим, — на сгиб всю кожу намотал.",0,822,0,0],["v","Обнажена лежит, белея, жертва…",0,823,0,0],["v","А времени… да на бегах скорей",0,824,0,0],["v","Не пробежит атлет два раза стадий…",0,825,0,0],["v","Когда же жертву вскрыли и Эгисф,",0,825,0,0],["v","Священную прияв ее утробу,",0,826,0,0],["v","Стал изучать: у печени главы",0,827,0,0],["v","Он не нашел, пузырь же и ворота",0,827,0,0],["v","Переполняла желчь, и тем они",0,828,0,0],["v","Гадателю недоброе сулили.<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,829,0,0],["v","Эгисф бледнеет, видим, — и к нему",0,830,0,1],["v","С вопросом наш владыка: «Что кручинен?»",0,830,0,0],["v","А тот в ответ: \"О гость, меня страшит",0,831,0,0],["v","Беда извне: для дома ж нет опасней",0,832,0,0],["v","Атридова отродья«. — »Как, Эгисф,",0,833,0,0],["v","Трепещешь ты скитальца козней? Царство ль —",0,834,0,0],["v","Тебе не щит? Однако дай же мне,",0,835,0,0],["v","Чтоб лакомства добыть из этой жертвы,",0,835,0,0],["v","Покрепче нож, с закалом фессалийским,",0,836,0,0],["v","Дробящим кость\".",0,837,0,0],["v","И вот удар ножа",1,837,0,0],["v","Вскрывает грудь. И только что над сердцем",0,838,0,0],["v","Внимательно склонился тот, <span class=\"ch\" data-ch=\"orest\">Орест</span>",0,839,0,0],["v","На цыпочках приподнялся и нож",0,840,0,1],["v","Царю всадил в загривок, а ударом",0,841,0,0],["v","Ему хребет ломает. Рухнул враг",0,842,0,0],["v","И заметался в муках, умирая.",0,843,0,0],["v","К оружию кидаются рабы",0,844,0,0],["v","И на двоих толпой. Но, сотрясая",0,845,0,0],["v","В руке копье, им мужи не сдались.",0,846,0,0],["v","И вот <span class=\"ch\" data-ch=\"orest\">Орест</span> взывает: \"Не разбойник",0,847,0,0],["v","Пришел на пир: домой вернулся царь…",0,848,0,0],["v","Я ваш <span class=\"ch\" data-ch=\"orest\">Орест</span> несчастный: не ищите ж",0,850,0,1],["v","За то, что я с убийцей порешил,",0,850,0,0],["v","Меня губить, рабы Агамемнона…\"",0,851,0,0],["v","Отпрянула толпа их, а <span class=\"ch\" data-ch=\"orest\">Орест</span>",0,852,0,0],["v","Был скоро там каким-то старцем признан.",0,853,0,0],["v","Торжественно увенчанный, тебе",0,854,0,0],["v","Он голову — не бойся, не Медузы —",0,855,0,0],["v","Эгисфа ненавистного несет.",0,856,0,0],["v","О, заплатил злодей с лихвой сегодня",0,857,0,0],["v","За кровь, что здесь когда-то проливал.",0,858,0,0],["sp","Хор"],["str","Строфа"],["v","Вплетись в хоровод наш, дева;",0,859,0,0],["v","Как легкая лань, в эфир",0,860,0,1],["v","Вздымайся пятой веселой!",0,860,0,0],["v","О, ярче венцов победы",0,861,0,0],["v","С брегов Алфея славных боец не уносил,",0,862,0,0],["sd","<span class=\"ch\" data-ch=\"elektra\">Электра</span> не хочет присоединиться к танцующим."],["v","Какие брат твой добыл. О, пой же, дева, пой!",0,863,0,0],["v","И под светлый напев мы плясать пойдем.",0,864,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, свет, о, блеск, о, колесница бога.",0,865,0,0],["v","Земля и ночь, царица слез моих,",0,866,0,0],["v","И вы, опять на белый свет свободно",0,867,0,0],["v","Отверстые зеницы. Да, Эгисф,",0,868,0,0],["v","Злодей, отца убийца, — он не встанет…",0,869,0,0],["v","Все, все сюда уборы и венцы!",0,870,0,1],["v","А вы со мной его венчайте, девы.",0,871,0,0],["sd","Во время пения следующей антистрофы первое непоющее полухорие входит в дом и выносит оттуда повязки, диадемы, цветы."],["sp","Хор"],["str","Антистрофа"],["v","Укрась ему кудри пышно,",0,872,0,0],["v","Мы ж, музам покорные,",0,873,0,0],["v","Затеем веселый танец.",0,874,0,0],["v","О, радость! Цари былые",0,875,0,0],["v","Опять над нами будут, любимые, царить…",0,876,0,0],["v","Неправедный не встанет — он правдою убит.",0,877,0,0],["v","Ты ж, о флейта, звучи, солнцем лейся, песнь…",0,878,0,0],["scene","Явление четырнадцатое","s16",4,16],["sd","Те же; <span class=\"ch\" data-ch=\"orest\">Орест</span> и Пилад (откуда-то пришли). За ними свита несет труп Эгисфа."],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","после пляски вместе с хором подходит к <span class=\"ch\" data-ch=\"orest\">Оресту</span>, затем к Пиладу: <span class=\"ch\" data-ch=\"orest\">Оресту</span> протягивает диадему, Пиладу — цветы"],["v","О славный сын венчанного отца",0,880,0,1],["v","В лучах его немеркнущей победы,",0,881,0,0],["v","Дай локоны обвить тебе, <span class=\"ch\" data-ch=\"orest\">Орест</span>.",0,882,0,0],["v","О, ты пришел не с бега, не на приз:",0,883,0,0],["v","Ты играми натешился, — врага",0,884,0,0],["v","Ты одолел, отцовского злодея.",0,885,0,0],["sd","(Пиладу.)"],["v","И ты венец, награду дел, прими,",0,886,0,0],["v","Воспитанный благочестивым мужем",0,887,0,0],["v","На радость нам, Пилад, а боги вам",0,888,0,0],["v","Да ниспошлют благой удел обоим!",0,889,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","отклоняя диадему"],["v","Богов почти, Электра, им воздай",0,890,0,1],["v","Хвалу, судьбы властителям могучим:",0,891,0,0],["v","Покорный раб их воли и судьбы,",0,892,0,0],["v","Эгисфа я убил, и это правда,",0,893,0,0],["v","А не молва, — а чтобы всякий мог",0,894,0,0],["v","Проверить нас, так вот тебе — убитый.",0,895,0,0],["sd","По его знаку слуги ставят носилки, и он сдергивает с трупа покрывало."],["v","И если ты скормить его зверям",0,896,0,0],["v","Иль пугалом для птиц, детей эфира,",0,897,0,0],["v","Прибить на столб захочешь, он на все",0,898,0,0],["v","Согласен — он твой раб, тиран вчерашний…",0,899,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Мне совестно, но речи жгут уста…",0,900,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Так говори. Кого ж тебе бояться?",0,901,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Глумления над трупом не простят.<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,902,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но чей же гнев возбудишь ты, царевна?",0,903,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Микенский люд угрюм и злоречив.",0,904,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Все ж волю дай желаньям… Нам с Эгисфом,",0,905,0,0],["v","Живым или убитым, мира нет.",0,906,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Итак, с чего ж начну и чем закончу,",0,907,0,0],["v","В средине что скажу я?.. А зари",0,908,0,0],["v","Я ни одной не провела, чтоб в мыслях",0,909,0,0],["v","Не размотать весь тот клубок речей,",0,910,0,1],["v","Которым бы свободная <span class=\"ch\" data-ch=\"elektra\">Электра</span>",0,911,0,0],["v","Ему в лицо швырнула.",0,912,0,0],["v","Час приспел.",1,912,0,0],["sd","(К трупу Эгисфа.)"],["v","Услышь же, что еще живой ты должен",0,913,0,0],["v","Был выслушать. Проклятый, без вины",0,914,0,0],["v","Сиротами за что ты нас оставил?",0,915,0,0],["v","С женой вождя слюбившись, вражьих стен",0,916,0,0],["v","Ты не видал… И в глупости надменной,",0,917,0,0],["v","Убийца, вор и трус, мечтать ты смел,",0,918,0,0],["v","Что взятая прелюбодейством будет",0,919,0,0],["v","Тебе женой примерной. Если кто,",0,920,0,1],["v","На ложе ласк обманом приклонивши",0,920,0,0],["v","Замужнюю, ей мужем станет и",0,921,0,0],["v","Вообразит, что скромною подругой",0,922,0,0],["v","Его чертог украсился, назвать",0,923,0,0],["v","Его нельзя счастливым. О, ты не был",0,924,0,0],["v","Так счастлив с ней, как, может быть, мечтал.",0,925,0,0],["v","Нечестия лобзанья не смывали",0,925,0,0],["v","С ее души, и низости твоей",0,926,0,0],["v","Средь пылких ласк она не забывала,",0,927,0,0],["v","И оба вы вкусили горький плод,",0,928,0,0],["v","Она твоих, а ты ее пороков.",0,929,0,0],["v","По всем устам ходило у микенян:",0,930,0,1],["v","«Царицын муж», а мать женой Эгисфа",0,930,0,0],["v","Не звал никто. О, горший из позоров,",0,931,0,0],["v","Когда в семье жена главой, а муж",0,932,0,0],["v","Так жалок, так принижен, что в народе",0,933,0,0],["v","По отчеству не кличут и детей.",0,934,0,0],["v","Да, истинно завидный брак — из дома",0,935,0,0],["v","Богатого и знатного добыть",0,935,0,0],["v","Жену и стать при ней еще ничтожней…",0,936,0,0],["v","На золото позарился Эгисф:",0,937,0,0],["v","Он им мечтал себе прибавить весу…",0,938,0,0],["v","Иль мы богатством прочны? Нет, сердец",0,939,0,0],["v","Сокровища природные, не деньги",0,940,0,1],["v","Нас вызволят из жизненных тисков.",0,940,0,0],["v","А золото с клеймом обид и зла",0,941,0,0],["v","На миг блеснет в чертоге — и пропало…",0,942,0,0],["v","Про женщин и Эгисфа не решусь",0,943,0,0],["v","Я говорить, как девушка. Но будет",0,944,0,0],["v","Довольно и намека. Он преград",0,945,0,0],["v","Себе не знал, кичась богатством нашим",0,945,0,0],["v","И красотой своей. О, если мне",0,946,0,0],["v","На выбор бы давали… Этих кукол",0,947,0,0],["v","Изнеженных суровому лицу",0,948,0,0],["v","Не предпочла бы я. Ареем дышит",0,949,0,0],["v","Отважный муж, а с этими куда?",0,950,0,1],["v","Иль в хоровод?",0,951,0,0],["v","Иди же в прах, невежда!",1,951,0,0],["v","Ты думал век царить — и нож один",0,952,0,0],["v","Мог вразумить тебя. А тело это",0,953,0,0],["v","Для всех урок: на играх пробежав",0,954,0,0],["v","В один конец, не обогнувши даже",0,955,0,0],["v","Меты, побед своих не объявляй…",0,956,0,0],["sp","Корифей"],["v","Он отдал вам за кровь богатый выкуп,",0,957,0,0],["v","И мощен был исконной Правды суд.",0,958,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Гей там, рабы! Возьмите труп и в угол,",0,959,0,0],["v","Да потемней, запрячьте,",0,960,0,1],["sd","(в сторону)"],["v","чтобы мать",0,960,4,0],["v","С любовником не свиделась до гроба.",0,961,0,0],["v","Труп уносят с носилками в ворота дома.",0,962,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","живо оборачивается и не глядя на брата"],["v","Оставь его… Пред нами новый путь.",0,962,0,0],["sd","(Делает несколько шагов вперед и всматривается в даль.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что видишь ты? Микенские отряды?",0,963,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","раздельно и тихо"],["v","Нет… Мать, меня носившую, <span class=\"ch\" data-ch=\"orest\">Орест</span>.",0,964,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","смотря в ту же сторону"],["v","Сиянье риз на блеске колесницы…",0,964,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","И в темноте расставленная сеть.",0,965,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нам убивать ее, подумай только…",0,966,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль этот блеск разжалобил тебя?",0,966,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Увы! Увы!",0,967,0,0],["v","Она меня носила и кормила:",0,968,0,0],["v","Как нож на грудь ее я подниму?",0,968,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","«Как?» — говоришь… ты мог бы поучиться",0,969,0,0],["v","У ней, когда покончила с отцом.",0,970,1,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О Феб! В тебе тогда вещал невежда…",0,971,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Невежда — Феб? Кто ж мудрый у тебя?",0,972,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не смеет сын убить ее, не смеет…",0,973,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","А кровь отца он смеет забывать?",0,974,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","В ее крови — клеймо и суд <span class=\"ch\" data-ch=\"orest\">Оресту</span>.",0,975,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль выберет проклятие отца?",0,976,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Гнев матери карать убийцу будет.",0,977,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Забудь отца — и бог тебя казнит.",0,978,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","подумав"],["v","Там демон был под маской Аполлона.",0,979,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль завладеть треножником он мог?",0,980,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет, нет… сюда оракул не подходит…",0,981,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","касаясь его руки, шепотом"],["v","Стыдись впадать в уныние… И мать",0,982,0,0],["v","Срази с такой же хитростью, с какою",0,983,0,0],["v","Они с Эгисфом извели отца.",0,984,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","останавливаясь перед входом"],["v","О, страшный путь, и ты, ужасный подвиг,",0,985,0,0],["v","Богами мне указанный, тебя,",0,986,0,0],["v","О, горький груз, подъемлю как невольник.",0,987,0,0],["sd","(Входит в дом.)"],["scene","Явление пятнадцатое","s17",4,17],["sd","На сцену выезжает богатая колесница с <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестрой</span>, несколько отяжелевшей, но все еще прекрасной; она расчесана, разряжена и нарумянена. Пешая свита из рабов и фригийских пленниц в богатых пурпурных и оранжевых пеплосах с золотыми брошками. Некоторые из них, покрасивей и понаряднее, едут за царицей на колесницах."],["sp","Хор"],["v","О, славься, царица аргосских полей!",0,988,0,0],["v","О чадо Тиндара,",0,989,0,0],["v","Ты храбрых Кронида сестра сыновей,",0,990,0,1],["v","Что в звездном сиянье эфира живут",0,990,0,0],["v","И факел горящий над бурей морской",0,991,0,0],["v","Для путника смертного держат…",0,992,0,0],["v","Блаженным подобна ты, слава тебе!",0,993,0,0],["v","В сиянье и счастье богатства живи!",0,994,0,0],["v","Я в прахе пред славой твоею лежу",0,995,0,0],["v","И блеском твоим, Тиндарида…",0,996,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","с колесницы"],["v","Насилу-то… Но прежде вы, троянки,",0,997,0,0],["v","Спуститесь вниз — вы будете опорой",0,998,0,0],["v","Для царских ног.",0,999,0,0],["sd","(Рассеянно смотрит вокруг и обращается больше к хору.)"],["sd","<span class=\"ch\" data-ch=\"elektra\">Электра</span> безмолвно и неподвижно стоит перед входной дверью. Рабыни спускаются с колесницы."],["v","Благодарить богов",1,999,0,0],["v","Фригийскою горит чертог добычей,",0,1000,0,1],["v","А этот цвет троянских жен за дочь",0,1001,0,0],["v","Убитую, конечно, жалкий выкуп,",0,1002,0,0],["v","Но наших зал микенских не теснит.",0,1003,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","приближаясь к матери и протягивая вместе с рабынями руки для ее поддержки"],["v","Дозволь рабе, из отчего чертога",0,1004,0,0],["v","Исторгнутой под этот бедный кров,",0,1005,0,0],["v","Блаженных рук, о мать, твоих коснуться.",0,1006,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","отстраняя ее руки"],["v","На это есть рабыни… Не трудись.",0,1007,0,0],["sd","(Спускается.)"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль плена я не видела, иль дома",0,1008,0,0],["v","Не лишена, иль не добыча я,",0,1009,0,0],["v","Подобно им, не сирота вдобавок?..",0,1010,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Отца вини, малютка. Вечно он",0,1010,0,0],["v","Вражды искал, терзая самых близких",0,1011,0,0],["v","Без их вины.",0,1012,0,0],["sd","(Хору.)"],["v","Вы ж слушайте, и пусть",0,1013,4,0],["v","За славою и речь мою порочит,",0,1013,0,0],["v","Как водится, пристрастный суд толпы…",0,1014,0,0],["v","Чернить — так за дела, и если точно",0,1015,0,0],["v","Кто ненависть делами заслужил —",0,1016,0,0],["v","Терпи ее, а если ненавидят,",0,1016,0,0],["v","Не рассудив, — что толку? Твоему",0,1017,0,0],["v","Отцу меня вручая, дед не думал,",0,1018,0,0],["v","Что дочь и вас убийце отдает…",0,1019,0,0],["v","А между тем Атрид, на брак с Ахиллом",0,1020,0,1],["v","Склонив дитя, в окованную гладь",0,1021,0,0],["v","Авлидскую увез ее обманом",0,1022,0,0],["v","И лилию скосил над алтарем…",0,1023,0,0],["v","О, я бы все простила, если город",0,1024,0,0],["v","Иначе им не взять бы, если б дом",0,1025,0,0],["v","Или детей спасал он этой жертвой,",0,1026,0,0],["v","Но он убил малютку за жену",0,1027,0,0],["v","Развратную, за то, что муж не смыслил",0,1028,0,0],["v","Изменницу достойно наказать.",0,1029,0,0],["v","О, я тогда смолчала — я к забвенью",0,1030,0,1],["v","Готовила уж сердце и казнить",0,1031,0,0],["v","Атрида не сбиралась. Но из Трои",0,1032,0,0],["v","Менаду царь безумную привез<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,1033,0,0],["v","На брачную постель и стал в чертоге",0,1034,0,0],["v","Двух жен держать. О жены, наш удел —",0,1035,0,0],["v","Слепая страсть. Пускай неосторожно",0,1036,0,0],["v","Холодность муж нам выкажет, сейчас",0,1037,0,0],["v","Назло ему любовника заводим,",0,1038,0,0],["v","И нас же все потом во всем винят,",0,1039,0,0],["v","Зачинщиков обиды забывая…",0,1040,0,1],["sd","(Помолчав.)"],["v","А если б был украден Менелай",0,1040,0,0],["v","И я б <span class=\"ch\" data-ch=\"orest\">Ореста</span> смертью выкупала",0,1041,0,0],["v","Сестре своей утеху, — иль отец",0,1042,0,0],["v","Стерпел бы твой?",0,1043,0,0],["v","Так, значит, смеет близких",0,1043,0,0],["v","Моих казнить Атрид, а мне терпенье",0,1044,0,0],["v","Предписано и жертвы?",0,1045,0,0],["sd","(Раздумчиво.)"],["v","Да, его",0,1046,4,0],["v","Убила я — мне не было дороги",0,1046,0,0],["v","Иной, как в стан его врагов. Друзья",0,1047,0,0],["v","Ему б обид моих не отомстили…",0,1048,0,0],["v","Ну, отвечай свободно… Коль убит",0,1049,0,0],["v","Неправдой он, ты мне докажешь это.",0,1050,0,1],["sp","Корифей"],["dir","царице"],["v","Да, ты права, но в правде — твой позор:",0,1051,0,0],["v","Нет, женщины, коли умом здоровы,",0,1052,0,0],["v","Мужьям во всем покорны, о больных",0,1053,0,0],["v","Я говорить не стану — тех со счетов…",0,1054,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Своих недавних слов не позабудь:",0,1055,0,0],["v","Ты мне сказать всю правду разрешила.",0,1056,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","И повторю, Электра, не таись.",0,1057,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Потом упрек слезой не отольется?",0,1058,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Нет, сладко мне увидеть дно души…",0,1059,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Мать, я начну с желания. О, если б",0,1060,0,1],["v","И сердце ты имела, как лицо,",0,1060,0,0],["v","Прекрасное. С Еленою вы обе",0,1061,0,0],["v","Прославились красою. Но — увы! —",0,1062,0,0],["v","Вы Кастора не стоите, и даром",0,1063,0,0],["v","Одна вас мать носила. Чародею,",0,1064,0,0],["v","Не споря с ним, Елена отдалась,",0,1065,0,0],["v","Ты ж лучшего меж греками убила…",0,1066,0,0],["v","Месть, говоришь, тебе точила нож?..",0,1067,0,0],["v","О, лги другим, а мы давно знакомы.",0,1068,0,0],["v","И дочь еще жила, и муж уйти",0,1069,0,0],["v","Едва успел, а золотые косы",0,1070,0,1],["v","Пред зеркалом ты убирала, мать…",0,1070,0,0],["v","А та жена, которая без мужа",0,1071,0,0],["v","Нарядится, — недобрая жена…",0,1072,0,0],["v","Иль побежит красой своей, без цели",0,1073,0,0],["v","И без дурной, она народ дивить?..",0,1074,0,0],["v","Но далее… ты, ты одна в Элладе",0,1075,0,0],["v","Успех врагов венчала блеском глаз",0,1076,0,0],["v","И радостью, а если счастье тылом",0,1077,0,0],["v","Вставало к ним, дарила их слезой,",0,1078,0,0],["v","Богов моля, чтоб муж не возвращался.",0,1079,0,0],["v","А как легко ты верною женой",0,1080,0,1],["v","Могла бы оставаться! Иль Эгисфу",0,1080,0,0],["v","Уступит муж, которого вождем",0,1081,0,0],["v","Эллада нарекла?",0,1082,0,0],["v","В самой Елене",1,1082,0,0],["v","Был для тебя, жена, богатый приз:<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,1083,0,0],["v","Дает и зло урок полезный добрым.",0,1084,0,0],["v","Ты говоришь, что дочь твою убил",0,1085,0,0],["v","Ее отец. А мы с <span class=\"ch\" data-ch=\"orest\">Орестом</span> разве",0,1086,0,0],["v","Обидели тебя? Зачем же дом",0,1087,0,0],["v","Ты отобрала отчий и, зарезав",0,1088,0,0],["v","Отца, себе на наши деньги мужа",0,1089,0,0],["v","Купила, мать? И почему Эгисф",0,1090,0,1],["v","В изгнании <span class=\"ch\" data-ch=\"orest\">Ореста</span> не заменит?",0,1090,0,0],["v","Как жить даешь ему? Казнив жреца",0,1091,0,0],["v","Моей сестры, ты ль палачу <span class=\"ch\" data-ch=\"elektra\">Электры</span>",0,1092,0,0],["v","Весь ужас мук ее прощаешь, мать?",0,1093,0,0],["v","О, если кровью кровь омыть мы властны,",0,1093,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> и я, за отчую — твою",0,1094,0,0],["v","Пролить должны, и если справедливо",0,1095,0,0],["v","Судила ты, то ты осуждена…",0,1096,0,0],["v","А человек, порочную приявший",0,1096,0,0],["v","В свой дом за блеск одежд и знатный род,",0,1097,0,0],["v","Он, верно, слеп. И не милее ль бедный,",0,1098,0,0],["v","Но скромностью украшенный приют.",0,1099,0,0],["sp","Корифей"],["v","На все судьба, иной так счастлив в браке,",0,1100,0,1],["v","Другому же одна беда с женой.",0,1101,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Я не дивлюсь речам твоим. Обычно,",0,1102,0,0],["v","Что дочери привязаны к отцу,",0,1103,0,0],["v","А сыновья — к носившей их нежнее.",0,1104,0,0],["v","И не сержусь. Увы, тоскою грудь",0,1105,0,0],["v","Сжимается и у меня, как вспомню,",0,1106,0,0],["v","Что я его убила… эти козни…",0,1107,0,0],["v","Весь этот гнев безумный… Горе мне…",0,1110,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, поздно, мать, — ты раны не залечишь:",0,1111,0,0],["v","Отец убит — но как до этих пор",0,1112,0,0],["v","Ты не вернешь домой скитальца-сына?",0,1113,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О дочь, боюсь: своя печаль больней.",0,1114,0,0],["v","Он, говорят, в изгнанье злобу копит.",0,1115,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль ярость ты в Эгисфе не смиришь?",0,1116,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Да, он суров. Но ведь и ты упряма.",0,1117,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Бессильная, я гнев свой подавлю.",0,1118,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Тогда и он к тебе добрее будет.",0,1119,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, как он горд. Забыл, что мой жилец!",0,1120,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Опять огонь потухший раздуваешь?",0,1120,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Молчу — в душе один глубокий страх…",0,1121,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Оставим лучше это. Посылала",0,1122,0,0],["v","За мною ты, дитя мое?",0,1123,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О да.",1,1123,0,0],["v","Я — мать, тебе, конечно, говорили…",0,1124,0,0],["v","Молю ж, заменой будь у алтаря",0,1125,0,0],["v","Неопытной. Ведь первенцу луна",0,1126,0,0],["v","Десятый раз свой факел зажигает…<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,1127,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Повившая пусть жертву принесет…",0,1128,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О мать, сама я повивала сына.",0,1129,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Иль никого у вас друзей окрест?",0,1130,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Кого ж она приманит, дружба нищих?",0,1130,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","И ты, едва покинув ложе мук,",0,1131,0,0],["v","Без ванны и в лохмотьях. О, войдем же!",0,1132,0,0],["v","Я жертвою десятую луну",0,1133,0,0],["v","Отпраздновать готова для малютки.",0,1133,0,0],["v","Не медли: ждет меня священный пир",0,1134,0,0],["v","В честь сельских нимф. А вы коней ведите,",0,1135,0,0],["v","Их ясли ждут.",0,1136,0,0],["sd","(Женщинам.)"],["v","Едва освобожусь",0,1136,4,0],["v","От жертвы, мы немедля уезжаем…",0,1137,0,0],["v","Не лишнее и мужу угодить.",0,1138,0,0],["sd","(Уходит.)"],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","сопровождая ее"],["v","Войди в наш бедный дом. Но осторожней,",0,1139,0,0],["v","Чтоб копотью от черных стен его",0,1140,0,1],["v","Ты пеплос не испортила. О, жертву",0,1141,0,0],["v","Ты должную бессмертным принесешь.",0,1142,0,0],["sd","(Вслед ей.)"],["v","Кошница ждет, и нож жреца отточен:",0,1143,0,0],["v","Зарезан бык, а рядом место есть…",0,1144,0,0],["v","О, там, во тьме Эреба, как под солнцем,",0,1145,0,0],["v","Ты ложе с ним разделишь. Получай",0,1146,0,0],["v","Свой долг сполна и расплатись со мною…",0,1147,0,0],["sd","(Уходит.)"],["scene","Третий музыкальный антракт","s18",4,18],["sp","Хор"],["str","Строфа"],["v","Отмщение злу! И нового ветра в чертоге дыханье!",0,1148,0,0],["v","Тогда над ванною царь",0,1149,1,0],["v","Поник главою венчанной,",0,1150,1,1],["v","И отдали крик и мраморный фриз, и стены тогда,",0,1150,0,0],["v","Исполненный муки:",0,1151,1,0],["v","\"Злодейка жена, не десять ли лет",0,1152,1,0],["v","Свиданья с родимой землей",0,1153,1,0],["v","Я ждал — и зарезан?\"",0,1154,1,0],["str","Антистрофа"],["v","Но мести волна, дыханием правды гонима, блудницу",0,1155,0,0],["v","К ним в сеть примчала… О ты,",0,1156,1,0],["v","О ты, что мужа убила",0,1157,1,0],["v","Меж каменных глыб, где долго его дворец ожидал,<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,1158,0,0],["v","Секирой железной",0,1159,1,0],["v","В преступной руке… О, сколько бы мук",0,1160,1,1],["v","Ты здесь ни подъяла, жена,",0,1161,1,0],["v","Безумно деянье.",0,1162,1,0],["v","Словно львица там, в черной тьме лесов,",0,1163,0,0],["v","Ты кровавый свой совершила грех…",0,1164,0,0],["act","Действие четвертое","a5","IV"],["sd","На сцене никого."],["v","Голос <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестры</span>",0,1165,0,0],["sd","(за сценой)"],["v","О, милосердие… Я мать… Не убивайте…",0,1166,0,0],["sp","Корифей"],["sd","Ты слышишь… крики там?"],["v","Голос <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестры</span>",0,1167,0,0],["sd","О, страшно! Ой, больно мне!"],["sp","Корифей"],["v","Она в руках детей — о, горький жребий!",0,1168,0,0],["sp","Хор"],["v","Суд божий свершится, и правда придет.",0,1169,0,0],["v","О, страшная доля, о, зверский трофей",0,1170,0,1],["v","Преступной расправы!",0,1171,0,0],["scene","Явление шестнадцатое","s19",5,19],["sd","Открывается задний план сцены с трупами <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестры</span>, плавающей в крови, и Эгисфа. Бледный, с потухшим взором и безоружный <span class=\"ch\" data-ch=\"orest\">Орест</span> и порозовевшая <span class=\"ch\" data-ch=\"elektra\">Электра</span>, в которой еще не улеглось волнение, — глаза у нее горят искрами."],["sp","Корифей"],["v","Идут, идут… Пропитанные кровью",0,1172,0,0],["v","Их матери зарезанной… О, вид",0,1173,0,0],["v","Трофея их победы нечестивой…",0,1174,0,0],["v","Нет дома, нет несчастнее тебя,",0,1175,0,0],["v","Дом Тантала… злосчастней и не будет…",0,1176,0,0],["scene","Коммос","s20",5,20],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["str","Строфа I"],["v","О матерь-земля, и ты, о небо, о стражи!",0,1177,0,0],["v","О смертных зоркие стражи!",0,1178,0,0],["v","О, вот вам два трупа —",0,1179,0,0],["v","Кровавое дело десницы моей,",0,1180,0,1],["v","Расплата за муки <span class=\"ch\" data-ch=\"orest\">Ореста</span>…",0,1180,0,0],["v",". . . . . . . . . . . . . . . . . . . .",0,1181,0,0],["v",". . . . . . . . . . . . . . . . . . . .",0,1182,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, тяжек грех, но он не твой, а мой:",0,1183,0,0],["v","Я на нее, родимую, напала,",0,1184,0,0],["v","Враждой палимая.",0,1185,0,0],["sp","Хор"],["v","Увы! О мать, как лют удел",0,1185,0,0],["v","Носившей и убитой.",0,1186,0,0],["v","Ты в море слез погружена, —",0,1187,0,0],["v","Пускай права была их месть, —",0,1188,0,0],["v","Детей родных руками, мать.",0,1189,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["str","Антистрофа I"],["v","О Феб-Аполлон, твой глас карать повелел мне.",0,1190,0,1],["v","На свет исчадия мрака",0,1191,0,0],["v","Воззвал ты, о вещий…",0,1192,0,0],["v","И, кровью десницу его загрязнив,",0,1193,0,0],["v","Изгнанье судил ты <span class=\"ch\" data-ch=\"orest\">Оресту</span>…",0,1194,0,0],["v","О, кто же, кто, праведный, даст мне",0,1195,0,0],["v","Приют, убившему мать?",0,1196,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Увы! Увы! Куда пойду теперь?",0,1197,0,0],["v","Подруги, где и кто <span class=\"ch\" data-ch=\"elektra\">Электру</span> примет",0,1198,0,0],["v","На ложе брачное?",0,1200,0,1],["sp","Хор"],["v","О, как покорна сердцем ты",0,1201,0,0],["v","Дыханью ветра, дева…",0,1202,0,0],["v","Так святы стали помыслы",0,1203,0,0],["v","Теперь твои. Увы, давно ль",0,1204,0,0],["v","На зло толкала брата ты?",0,1205,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["str","Строфа II"],["v","Видала ль ты, как горькая из-под одежды",0,1206,0,0],["v","Достала грудь, чтоб у убийцы дрогнул нож?",0,1207,0,0],["v","Увы, увы! Как мне она,",0,1208,0,0],["v","Там, на коленях ползая, терзала сердце!",0,1209,0,0],["sp","Хор"],["v","О, сколько мук ты вытерпел, увы,",0,1210,0,1],["v","Внимая стонам нежных уст",0,1211,0,0],["v","Родимой матери!",0,1212,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["str","Антистрофа II"],["v","Она, к лицу убийцы руки протянув,",0,1213,0,0],["v","Рыдала там: «О, сжалься надо мной, дитя»,",0,1214,0,0],["v","И шею так в мольбе она",0,1215,0,0],["v","Мне обняла, что уронил и меч убийца-",0,1216,0,0],["sp","Хор"],["v","Несчастная! Как этот страшный вид",0,1217,0,0],["v","Ты снес ее предсмертных мук,",0,1218,0,0],["v","Убийца матери?",0,1220,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["str","Строфа III"],["v","Меж складками плаща лицо я спрятал,",0,1220,0,0],["v","И меч тогда занес,",0,1221,0,0],["v","И в грудь ей погрузил клинок.",0,1222,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Звала тебя, толкала я,",0,1223,0,0],["v","С тобою меч вздымала я…",0,1224,0,0],["sp","Хор"],["v","О, горе вам, преступные!",0,1225,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["str","Антистрофа III"],["v","Сестра, набрось лоскут на это тело",0,1226,0,0],["v","И раны ей закрой.",0,1227,0,0],["sd","(К трупу.)"],["v","Убийц своих носила ты…",0,1228,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["dir","набросив одежду на труп <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестры</span>"],["v","Покойся ж под плащом моим,",0,1229,0,0],["v","Любимая, постылая…",0,1230,0,1],["sp","Хор"],["v","Конец тебе, о славный дом!",0,1231,0,0],["sd","⟨ИСХОД⟩"],["sp","Корифей"],["dir","открывает словами исход"],["sd","Во время следующих слов его над домом вырисовываются из белого тумана фигуры Диоскуров."],["scene","Явление семнадцатое","s21",5,21],["v","Но что там, над домом в эфире?",0,1232,0,0],["v","Иль демоны это? Иль с выси святой",0,1233,0,0],["v","Небесные боги? Стопа человека еще",0,1234,0,0],["v","Туда не ступала… Могу я",0,1235,0,0],["v","Богов различить… Но разве",0,1236,0,0],["v","Им место меж нами?..",0,1237,0,0],["sp","Кастор"],["v","Внемли, о сын Атрида, Диоскурам",0,1238,0,0],["v","И братьям той, которой ты рожден.",0,1239,0,0],["v","Я Кастор, вот близнец мой Полидевк…",0,1240,0,1],["v","В пучине мы едва волненье злое",0,1240,0,0],["v","Утишили, как Аргос нам явил",0,1241,0,0],["v","Здесь труп сестры, твоей несчастной жертвы.",0,1242,0,0],["v","Она была достойна кары, но…",0,1243,0,0],["v","Но не твоей, <span class=\"ch\" data-ch=\"orest\">Орест</span>. Об Аполлоне,",0,1244,0,0],["v","Как о царе своем, я умолчу,",0,1245,0,0],["v","Иль преступить ума не может мудрый?",0,1246,0,0],["v","Но покорись! А жребий и Кронид",0,1247,0,0],["v","Судьбу твою решили. Вот послушай:",0,1248,0,0],["v","Ты, в жены дав сестру Пиладу, сам",0,1249,0,0],["v","Родной предел покинешь; непристойно",0,1250,0,1],["v","Убившему родную мать входить",0,1250,0,0],["v","В аргосский кремль. Как тень, метаться будешь,",0,1251,0,0],["v","А за тобою прыгать неустанно",0,1252,0,0],["v","И страшные и злые псицы: их",0,1253,0,0],["v","Божественна природа — это Керы.",0,1253,0,0],["v","В скитаниях когда придешь, Орест,",0,1254,0,0],["v","В Афины, там есть истукан Паллады,",0,1255,0,0],["v","Прижмись к нему, — Эринии тебя",0,1256,0,0],["v","Покинут вмиг; тебя эгидой стоит",0,1256,0,0],["v","Ей осенить — и очарует змей…",0,1257,0,0],["v","А в городе есть холм Арея: древле",0,1258,0,0],["v","Впервые там судился бог войны,<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,1259,0,0],["v","Когда убил исчадье Посейдона,",0,1260,0,1],["v","Ругателя дочернего казня.",0,1260,0,0],["v","Решения Ареопага святы,",0,1261,0,0],["v","И хоть теперь должны звучать они",0,1262,0,0],["v","Из смертных уст — все ж слово непреложно…",0,1263,0,0],["v","И ты, Орест, свой примешь приговор",0,1264,0,0],["v","С того холма. И половина скажет:",0,1265,0,0],["v","Виновен ты, а половина — нет,",0,1265,0,0],["v","Но Локсий сам, оракулом смутивший",0,1266,0,0],["v","Тебя, вину Орестову возьмет…",0,1267,0,0],["v","И с этих пор войдет в закон, коль мненья",0,1268,0,0],["v","Где поровну поделятся — прощать.",0,1269,0,0],["v","Эринии ж, сраженные обидой,",0,1270,0,1],["v","У самого холма поглощены",0,1270,0,0],["v","Жерлом подземным будут, чтобы после",0,1271,0,0],["v","Из пропасти, пожравшей их, вещать.",0,1272,0,0],["v","Оттуда путь тебе к брегам Алфея,",0,1273,0,0],["v","В Аркадию, где дивен Зевсов храм.",0,1274,0,0],["v","И в честь твою там город будет назван.<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,1275,0,0],["v","А трупы пусть: Эгисфов — похоронят",0,1276,0,0],["v","Аргосские сограждане, а мать —",0,1277,0,0],["v","Царь Менелай, вернувшийся из Трои,",0,1278,0,0],["v","Земле с сестрой Еленой предадут.",0,1279,0,0],["v","В Протеевом таилася чертоге",0,1280,0,1],["v","Сестра моя Елена: только тень",0,1281,0,0],["v","Ее Кронид явил предметом тяжких",0,1282,0,0],["v","И распрей и убийства. Пусть Пилад",0,1283,0,0],["v","Теперь берет себе <span class=\"ch\" data-ch=\"elektra\">Электру</span> в жены",0,1284,0,0],["v","И с ней идет в Ахайю, а того,<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,1285,0,0],["v","Который был твоим названым зятем,",0,1286,0,0],["v","Пускай пошлет в Фокиду, и с дарами…<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,1287,0,0],["v","А ты, Орест, стопы направь на Истм,<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,1288,0,0],["v","К брегам Кекропии блаженной ближе…",0,1289,0,0],["v","О, тяжесть мук убийцы пережив,",0,1290,0,1],["v","Свободен ты и долго счастлив будешь.",0,1291,0,0],["sp","Корифей"],["v","О Зевса сыны! Божественный слух",0,1292,0,0],["v","Мы ваш утрудить дерзнем ли мольбой?",0,1293,0,0],["sp","Кастор"],["v","Дерзайте: вас кровь, о девы, не кроет!..",0,1294,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А к речи <span class=\"ch\" data-ch=\"orest\">Ореста</span> склоните ль вниманье?",0,1295,0,0],["sp","Кастор"],["v","О да, Аполлон подъемлет вину",0,1296,0,0],["v","И крови и зла.",0,1297,0,0],["sp","Корифей"],["v","Вы боги и братьями были",0,1298,0,0],["v","Убитой жены…",0,1299,0,0],["v","Зачем же, зачем этот ужас?..",0,1300,0,1],["sp","Кастор"],["v","Тяжелый млат судьбы сковал",0,1301,0,0],["v","Худую речь для вещих уст.",0,1302,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Иль и меня его глагол",0,1303,0,0],["v","Кровь матери пролить опутал?",0,1304,0,0],["sp","Кастор"],["v","На общее дело одна вас сковала",0,1305,0,0],["v","Обоих судьба,<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,1306,0,0],["v","Проклятие в роде сгубило…",0,1307,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Сестра дорогая! Тебя не видал я",0,1308,0,0],["v","Так долго и ласки минутной лишаюсь,",0,1309,0,0],["v","Тебя покидая, тобою покинут.",0,1310,0,1],["sp","Кастор"],["v","Ей дом остается и муж, и ее",0,1311,0,0],["v","Не в горе покинешь; но город",0,1312,0,0],["v","Аргосский ей, точно, не видеть…",0,1313,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О, есть ли в груди стенанья больнее",0,1314,0,0],["v","Стенаний разлуки с отчизной?",0,1315,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Увы! От палат отцовских вдали",0,1316,0,0],["v","Чужими судим я буду за кровь",0,1317,0,0],["v","Родимой.",0,1318,0,0],["sp","Кастор"],["v","Дерзай! Ты придешь",1,1318,0,0],["v","К священным стенам Паллады… дерзай!",0,1320,0,1],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","О милый <span class=\"ch\" data-ch=\"orest\">Орест</span>! Ты грудью ко мне",0,1321,0,0],["v","Прижмись, и нежнее:",0,1322,0,0],["v","Оторваны мы от сени отцов,",0,1323,0,0],["v","О матери кровь, проклятьем твоим.",0,1324,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты к сердцу прильни и плачь надо мной,",0,1325,0,0],["v","О, плачь, как над мертвым в могиле!",0,1326,0,0],["scene","Сцена плача","s22",5,22],["sp","Кастор"],["v","Прощальная речь… Как страшно звучишь",0,1327,0,0],["v","Ты в сердце бессмертном!",0,1328,0,0],["v","Вы ж, о муки людей, обреченных страдать,",0,1329,0,0],["v","Вы слезой закипаете в боге…<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1330,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не видеть тебя!",0,1331,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Лучами очей не сливаться!",0,1332,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","С нежных уст, о последний привет…",0,1333,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Ты, о город, прости!",0,1334,0,0],["v","Будьте счастливы долго, подруги.",0,1335,0,0],["sd","(Собирается уходить.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Уходишь… так скоро… а дружба и клятвы?",0,1336,0,0],["sp","<span class=\"ch\" data-ch=\"elektra\">Электра</span>"],["v","Лицо мое слезы покрыли… Прости мне…",0,1337,0,0],["sd","(Уходит с Пиладом.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","вослед Пиладу"],["v","Прощай же и ты, о Пилад,",0,1340,0,1],["v","Будь мужем <span class=\"ch\" data-ch=\"elektra\">Электры</span> и счастлив.",0,1340,0,0],["sd","Мимическая сцена. <span class=\"ch\" data-ch=\"orest\">Орест</span> болезненно съеживается и делает прыжок. Глаза его беспокойно горят и бегают. Он готов бежать."],["sp","Кастор"],["v","Оставь их… а сам скрывайся, беги",0,1341,0,0],["v","К Афинам… Ты видишь, уж вот они, вот:",0,1342,0,0],["v","Собаки ужасные рвутся к тебе;",0,1343,0,0],["v","Не лапы, а змеи, как уголь черны,",0,1344,0,0],["v","И сладки им муки людские…",0,1345,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> убегает, дрожа, большими прыжками.",0,1346,0,0],["v","А мы к сицилийским волнам поспешим",0,1347,0,0],["v","Спасать корабли среди бури.",0,1348,0,0],["v","Преступное сердце с эфирных высот",0,1349,0,0],["v","Спасенья от нас не увидит,",0,1350,0,1],["v","Но тот, кто и правду, и долг свой хранил,",0,1351,0,0],["v","И жизнь не позорит, тот мил нам:",0,1352,0,0],["v","Его и под грузом нужды сбережем.",0,1353,0,0],["v","О смертный: обид и нарушенных клятв",0,1354,0,0],["v","Страшися. И свят и свободен,",0,1355,0,0],["v","Тебе говорю, как бессмертный и бог.",0,1356,0,0],["sd","(Исчезает.)"],["sp","Корифей"],["v","О, радуйтесь… вы, кому радость дана.",0,1357,0,0],["v","Кто бедствия чужд и не страждет,",0,1358,0,0],["v","Не тот ли меж смертными счастлив?<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,1359,0,0],["sd","Хор молча покидает сцену под мерные звуки ударных инструментов, отбивающих такт."],["h1","Комментарий","comm"],["p","Трагедия поставлена скорее всего в 413 г. до н. э.: в ст. 1280 — 1283 Еврипид набрасывает план своей трагедии «Елена», поставленной в следующем, 412 г., а появляющиеся в финале Диоскуры сообщают о своем намерении отправиться в район Сицилии, чтобы оберегать там от морских бурь корабли (ст. 1347 сл.). Эти слова, не имеющие никакого отношения к действию трагедии, могли быть понятны в Афинах лишь весной 413 г., после того как в Сицилию только что отбыл большой вспомогательный флот во главе с полководцем Демосфеном; в Сицилию корабли прибыли в июле (Фукидид, VII, 20,42), и естественно, что за время их плавания афиняне не раз имели основание тревожиться о судьбе своих близких."],["p","Миф о печальном возврате Агамемнона из-под Трои и о мести, свершенной его сыном Орестом над убийцами отца, восходит, вероятно, еще к микенской эпохе и издавна являлся предметом эпических сказаний. Во всяком случае, воспоминания об участниках этих событий, содержащиеся в «Одиссее» (1, 29 — 43, 294 — 296; III, 195 — 198, 248 — 275, 303 — 310; IV, 512 — 537; XI, 405 — 439; XXIV, 199 — 202), показывают, что история убийства Агамемнона была хорошо известна и автору поэмы, и его слушателям. Первую литературную обработку она получила, очевидно, в послегомеровском эпосе — поэмах «Киприи» и «Возвращения». В первой из них уже был подробно разработан мотив жертвоприношения Ифигении (см. вступительную заметку к «Ифигении в Тавриде»), который делал более обоснованным участие Клитемнестры в убийстве Агамемнона; теперь оно могло быть объяснено местью за погубленную дочь. Дальнейшее развитие мифа произошло в хоровой лирике VI в., главным образом в двухчастной «Орестее» Стесихора, во многом использованной Эсхилом в трилогии под тем же названием. Из нескольких трагедий Софокла, принадлежавших к этому кругу мифов, сохранилась только «Электра», дата которой неизвестна, и исследователи до сих пор не могут прийти к единому мнению, какая из двух «Электр» — Софокла или Еврипида — написана раньше. В любом случае несомненно, что в изложении событий, как предшествующих действию «Электры», так и предстоящих после его окончания, Еврипид достаточно близко следует сложившейся традиции, особенно — Эсхилу."],["p","При возвращении в дом Агамемнону было устроено, как полагалось путнику, омовение в бане; здесь он и был убит Клитемнестрой (ст. 157 сл., 1148 — 1150), отмстившей ему за жертвоприношение Ифигении и связь с Кассандрой (ст. 29, 1032 — 1034). Роль Эгисфа при этом не вполне ясна — то говорится, что Агамемнон, коварно обманутый Клитемнестрой, погиб от руки Эгисфа (ст. 122 — 124), то убийцей названа одна Клитемнестра (ст. 1155 — 1160), а Эгисф — ее вдохновителем (ст. 159 — 166), то в непосредственном убийстве царя обвиняются оба (ст. 85 — 87). Так или иначе, они должны стать жертвами мести Ореста, чья дальнейшая судьба излагается здесь (ст. 1250 -1272) в том же духе, как в «Ифигении в Тавриде» (см. ст. 940 — 969 и примеч. к ним). Что же касается фиктивного брака Электры с микенским пахарем, а особенно — отношения Ореста к убийству матери, то здесь, напротив, Еврипид занимает совершенно новую позицию, принципиально отличную по сравнению с Эсхилом и Софоклом (см. вступит, статью, с. 581)."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"]],"n":{"k1":["Ст. 1. Инах","речка в северо-восточном Пелопоннесе, втекающая в Арголидский залив. На ее правом берегу, недалеко от устья, находился Аргос."],"k2":["Ст. 20 — 21. …со всей Эллады сватать съезжалась знать.","Мотив, не известный из других античных источников."],"k3":["Ст. 27","К детенышу… любовь живет… — сильно расширенный переводчиком образ оригинала, где сказано только: «Мать, хоть и жестокая, спасла ее от руки Эгисфа»."],"k4":["Ст. 116. Тиндарида","здесь: Клитемнестра, дочь Тиндарея. «Родословная» Электры переведена Анненским с изощренностью, чуждой оригиналу, где сказано: «Я родилась от Агамемнона и Клитемнестры, ненавистной дочери Тиндарея»."],"k5":["Ст. 171 — 174. …к… Гере в Аргосский храм девы сбираются…","Речь идет о большом празднестве в честь Геры, покровительницы Аргоса (см. Геродот, I, 31), которое справлялось в священном округе Гереоне, примерно в восьми километрах от Аргоса."],"k6":["Ст. 214. Тиндарида","здесь: другая дочь Тиндарея — Елена, виновница Троянской войны и всех связанных с нею бедствий."],"k7":["Ст. 215 — 219. …там чужие…","В незнакомцах Электра подозревает, очевидно, убийц, подосланных Эгисфом."],"k8":["Ст. 317. Аграф","металлическая застежка."],"k9":["Ст. 367 — 390","Размышления, обнаруживающие скептическое отношение Еврипида к врожденной доблести и преимуществам аристократического воспитания."],"k10":["Ст. 410. Танай (Танаос или Танос)","река, протекающая через область Фиреатиду, лежащую между Арголидой и Спартой и неоднократно служившую предметом пограничных споров. В конце V в. Фиреатида принадлежала спартанцам."],"k11":["Ст. 432 — 486","Еще один образец «дифирамбического стасима» (см. примеч. к «Гекубе», ст. 905 — 952, и к «Ифигении в Тавриде», ст. 1234 — 1283), весьма отдаленно связанного с содержанием трагедии; внимание поэта привлекают живописные детали прибытия греческого флота под Трою (ст. 432 — 441) и щита Ахилла (ст. 442 — 469). Этим интересом к созданию самодовлеющей картины объясняется контаминация в ст. 442 — 469 сведений, относящихся к разным щитам Ахилла и соединенных между собой без достаточной последовательности. Так, в рассказе хора речь идет, по-видимому, о тех доспехах, в которых Ахилл прибыл под Трою из своего родного края — Фтии Фессалийской; именно сюда морские богини Нереиды должны были принести ему вооружение, минуя горные хребты Пелий и Оссу. Согласно эпосу, однако, Ахилл взял с собой под Трою доспехи, подаренные богами его отцу Пелею в день свадьбы с Фетидой («Илиада», XVII, 194 — 197; XVIII, 84 сл.), — для того чтобы получить это вооружение, хранившееся в доме отца, Ахиллу не требовались услуги Нереид. Когда же доспехи Ахилла, надетые в бой Патроклом, оказались в руках Гектора, Гефест, по просьбе Фетиды, изготовил для Ахилла новые, и Фетида доставила их сыну в лагерь под Троей («Илиада», XVIII, 130 — 148, 369 — 616; XIX, 1 — 13), опять же без помощи Нереид, которых, впрочем, не трудно было с ней соединить: уже в эпосе Фетида в сопровождении своих сестер являлась утешать Ахилла после гибели Патрокла («Илиада», XVIII, 35 — 69), а в трагедии Эсхила «Нереиды», названной так по хору, они как раз приносили герою новое вооружение. Но в этом случае им явно незачем было искать Ахилла в Фессалии, и, таким образом, их маршрут через Пелий и Оссу снова остается необоснованным. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Гекуба», Ст. 905-952. Этот стасим.</b> первый в творчестве Еврипида образец повествовательной хоровой песни, напоминающей аттические дифирамбы Вакхилида. В более поздних трагедиях связь таких «дифирамбических стасимов» с основным содержанием трагедии становится еще менее прочной.</span><!--/xn--> <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 1234-1283.</b> «Дифирамбический стасим» (см. примеч. к «Гекубе», ст. 905-952), почти не связанный с содержанием трагедии. Речь идет об учреждении дельфийского прорицалища Аполлона. Первоначально здесь находился оракул Фемиды, охраняемый драконом Пифоном: убив дракона, Аполлон завладел прорицалищем. Несколько иначе этот миф излагается в так называемом гомеровском гимне к Аполлону Пифийскому (ст. 171-196) и в «Евменидах» Эсхила, ст. 1-20. В антистрофе (1259 сл.) используется, по-видимому, какая-то храмовая легенда о соперничестве Аполлона с бывшей владелицей прорицалища.</span><!--/xn-->"],"k12":["Ст. 435 — 437","…очарованный трелью флейты, дельфин играл… — О любви дельфинов к музыке повествовала знаменитая легенда о спасении певца Ариона; здесь речь идет о звуках флейты, посредством которых давался ритм гребцам."],"k13":["Ст. 441. Симунт (Симоент)","река на Троянской равнине."],"k14":["Ст. 452 сл","Щит твой, о сын Нереиды… — Поскольку Еврипид описывает первый щит Ахилла, хор не может сослаться на традицию, идущую от эпических певцов, и в качестве источника своих сведений называет какого-то человека, от которого он слышал рассказ о щите Ахилла в порту Навплии, на берегу Арголидского залива. Естественно, что изображения на этом щите не совпадают с теми, которые сделал Гефест на втором щите, кроме солнца и созвездий, помещенных в центре щита (ср. ст. 464 — 468 и «Илиада», XVIII, 483 — 489)."],"k15":["Ст. 469. …Гиад и Плеяд, Приамида сразивших.","Неточный перевод. Созвездия Гиад и Плеяд не являлись виновниками гибели Гектора («Приамида») ни в прямом, ни в переносном смысле слова: Гектор был сражен, естественно, копьем Ахилла, а не его щитом. В оригинале речь идет о том, что Гектору приходилось отвращать взоры от сверкающего щита Ахилла, подобно тому как в «Илиаде» (XXII, 134 — 137) Гектор обращается в бегство при виде сияния, исходящего от доспехов Ахилла (ср. также XDC, 14 сл.)."],"k16":["Ст. 474 — 475. Лев… что за дивно крылатым конем… следил…","На панцире Ахилла было изображено сражение Беллерофонта, оседлавшего крылатого коня Пегаса, с Химерой — чудовищем, имевшим голову льва, тело козы и хвост дракона."],"k17":["Ст. 527 — 546","Еврипид откровенно полемизирует с изложением мифа у Эсхила в «Хоэфорах» (ст. 168 — 234), где отрезанный локон Ореста, след от его ноги у могилы Агамемнона и знак, вышитый рукой Электры на одежде брата, служили для его опознания."],"k18":["Ст. 659. Но где ж мета?","Образ заимствован из лексикона спортивных состязаний: старику кажется, что Электра не ясно различает конечную цель своего плана, подобно бегуну или возничему, не видящему меты, которую он должен обогнуть."],"k19":["Ст. 671 — 683","Принятое Анненским распределение реплик, соответствующее рукописи, отвергается большинством издателей текста. Вероятнее всего, эти 12 стихов представляют собою стихомифию с участием Ореста, Электры и старика. Первая реплика принадлежит Оресту."],"k20":["Ст. 684. Все слышит он…","Скорее всего этот стих представляет реплику старика, более точный перевод которой таков: «Все слышит он, но нам пора идти». В ст. 685 Электра прямо называет имя Эгисфа."],"k21":["Ст. 699 — 736","Содержание этого стасима составляет сказание о вражде детей Пелопа — Атрея и Фиеста (см. примеч. к «Ифигении в Тавриде», ст. 194 — 200). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 194-200. Гелия яркое око….</b> Речь идет о вражде детей Пелопа — Атрея и Фиеста. В стаде Атрея появился златорунный ягненок, и прорицатели истолковали это как знамение, дающее Атрею право на царский престол в Аргосе. Фиест, соблазнив жену Атрея Аэропу, выкрал при ее помощи златорунного ягненка и предъявил его в народном собрании, претендуя на царскую власть. Тогда Зевс по просьбе Атрея послал новое знамение, подтверждающее его права: солнце изменило свой прежний путь и стало передвигаться с запада на восток.</span><!--/xn-->"],"k22":["Ст. 745 — 746. Только эти два стиха имеют непосредственное отношение к содержанию трагедии, подготовляя как приход Клитемнестры, сестры прославленных братьев","Диоскуров, так и их собственное появление в финале."],"k23":["Ст. 781. …на берега Алфея…","То есть в храм Зевса в Олимпии (см. примеч. к «Ипполиту», ст. 535). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ипполит», Ст. 535. Алфей.</b> река в Элиде; на ее правом берегу находился город Олимпия со знаменитым храмом Зевса. Пифийские храмы — святилища в Дельфах. Бычьи туши — гекатомбы, когда приносилось в жертву целое стадо быков.</span><!--/xn-->"],"k24":["Ст. 826 — 829. …утробу, стал изучать…","По расположению внутренностей жертвенных животных гадатели предсказывали будущее и в современных Еврипиду Афинах, и еще много столетий спустя — в Риме. Неудивительно, что в «героическую» эпоху царские и жреческие функции сосредоточивались в одних руках."],"k25":["Ст. 902. Глумления над трупом не простят.","Ср. «Одиссея», XXII, 412. Ст. 1002. За дочь убитую — за Ифигению."],"k26":["Ст. 1032 — 1034. Менаду царь безумную привез…","Кассандру (см. «Гекуба», ст. 825 — 832 и примеч. к ст. 120 сл.). Клитемнестра изображает дальше дело таким образом, будто взяла себе в любовники Эгисфа, чтобы отомстить Агамемнону за измену с Кассандрой; между тем вся предшествующая Еврипиду литературная традиция считала именно давнишнюю связь Клитемнестры с Эгисфом причиной убийства Агамемнона. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Гекуба», Ст. 120. …вещей вакханки твоей….</b> Кассандры. После падения Трои Агамемнон получил в качестве пленницы-наложницы Кассандру, дочь Гекубы, наделенную пророческим даром.</span><!--/xn-->"],"k27":["Ст. 1083 — 1085. В самой Елене был для тебя, жена, богатый приз…","Электра хочет сказать, что на фоне безнравственного поведения Елены могла бы еще выгоднее выделяться добродетель Клитемнестры."],"k28":["Ст. 1126 — 1127. Ведь первенцу луна десятый раз свой факел зажигает.","На десятый день после родов полагалось созвать родных для жертвоприношения и угощения; тогда же давалось имя новорожденному."],"k29":["Ст. 1158. Меж каменных глыб…","См. примеч. к «Гераклу», ст. 15. Ст. 1181. После этого стиха, как видно из сопоставления с антистрофой, в рукописях утеряны два стиха. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Геракл», Ст. 15. Град киклопов..</b> Обычно так называли Микены, обнесенные в древности крепостной стеной «киклопической кладки» (см. сг. 944); в V в., после разрушения Микен соседним с ними Аргосом, на последний стали переносить легендарную характеристику Микен.</span><!--/xn-->"],"k30":["Ст. 1259. Впервые там судился бог войны…","См. примеч. к «Ифигении в Тавриде», ст. 940 — 969. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 940-969.</b> История Ореста излагается здесь в основном по «Евменидам» Эсхила; см. особенно ст. 940-945, 959-969. Однако название Ареопага Еврипид выводит из первого суда, который якобы состоялся на этом холме, над Аресом, убившим Галиррофия, сына Посейдона (иначе у Эсхила, ст. 685-690), и вводит такую деталь, как разделение Эриний на два лагеря; не признавшие решения Ареопага продолжают преследовать Ореста, без чего весь «таврический» вариант мифа не мог быть согласован с рассказом о суде в Афинах, оправдавшем Ореста.</span><!--/xn-->"],"k31":["Ст. 1275. Город будет назван.","Город Орестеон в Аркадии, вблизи города Ликеона, где находился храм Зевса."],"k32":["Ст. 1285. Ахайя","область на северо-западе Пелопоннеса."],"k33":["Ст. 1287. Фокида","область к северу от Коринфского залива, в которой расположены Дельфы."],"k34":["Ст. 1288 сл. Истм","Коринфский перешеек; Кекропией Еврипид называет Афины по имени их древнейшего царя Кекропа."],"k35":["Ст. 1292 — 1359","Вся заключительная часть трагедии написана анапестическими диметрами, которые переданы переводчиком только отчасти."],"k36":["Ст. 1306","Проклятие в роде Атридов связано с заносчивостью Тантала (см. «Орест», ст. 10 и примеч.; «Ифигения в Тавриде», ст. 388), вероломством Пелопа (см. примеч. к «Ифигении в Тавриде», ст. 191 — 193), прелюбодеянием Фиеста и жертвоприношением Ифигении. Следует, однако, отметить, что мотив родового проклятия появляется здесь только для того, чтобы еще больше подчеркнуть бессмысленность происходящего. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Орест», Ст. 10. …С надменным царь не сладил языком..</b> Еврипид несколько видоизменяет миф, приписывая Танталу не разглашение тайны, а дерзкие речи во время самого пира богов; он принимает также какую-то малоизвестную версию, согласно которой Тантал был подвешен на цепи между небом и землей, в то время как над ним нависала угрожающая падением скала (см. также ст. 982 — 987).</span><!--/xn--> <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 191-193.</b> Греческий текст дошел здесь в плохой сохранности, и переводчик дает скорее пояснение, чем перевод. Чтобы добиться руки дочери Эномая (ср. ст. 1 сл.), Пелоп должен был обогнать его в состязании на колесницах; неудачливых претендентов Эномай убивал. Пелоп подкупил Миртила, возницу Эномая, который вынул болт из чеки колесницы своего господина, и таким образом Пелоп одержал победу. Впоследствии, чтобы избавиться от свидетеля своего преступления, он столкнул Миртила в море.</span><!--/xn-->"],"k37":["Ст. 1329 — 1330. …о муки людей… вы слезой закипаете в боге…","Высказывание, противоречащее обычному убеждению Еврипида в безразличии богов к страданиям смертных."]},"mainEnd":2051,"c":[{"id":"elektra","name":"Электра","role":"Дочь Агамемнона","intro":"Царевна, выданная Эгисфом за бедного пахаря, чтобы её дети не могли мстить.","arc":"Еврипидова Электра живёт в деревне в лохмотьях и носит воду, хотя пахарь бережёт её девственность. Её ненависть к матери и Эгисфу доходит до одержимости: она сама заманивает мать в хижину. После убийства её одолевает ужас.","st":[{"i":125,"p":6,"l":"Пролог · явление второе","t":"Жизнь в изгнании","d":"Идёт за водой; рассказывает пахарю о своём горе.","c":"","k":false},{"i":527,"p":26,"l":"Действие первое · явление шестое","t":"Встреча с незнакомцем","d":"Не узнаёт брата и просит передать Оресту всё о её жизни.","c":"","k":false},{"i":1117,"p":54,"l":"Действие второе · явление одиннадцатое","t":"Узнавание","d":"Старик узнаёт Ореста по шраму; Электра обнимает брата. Планируют месть.","c":"","k":true},{"i":1526,"p":74,"l":"Действие третье · явление четырнадцатое","t":"Над телом Эгисфа","d":"Произносит обличительную речь над трупом врага; ободряет колеблющегося Ореста.","c":"","k":false},{"i":1752,"p":85,"l":"Действие третье · явление пятнадцатое","t":"Встреча с матерью","d":"Заманивает Клитемнестру ложной вестью о родах и обвиняет её.","c":"Сама ведёт мать на смерть.","k":true},{"i":1882,"p":92,"l":"Действие четвертое · Коммос","t":"Раскаяние","d":"Вместе с Орестом в ужасе от совершённого.","c":"","k":false},{"i":2001,"p":98,"l":"Действие четвертое · явление семнадцатое","t":"Приговор Диоскуров","d":"Кастор велит ей стать женой Пилада и покинуть Аргос.","c":"","k":false}],"gen":"Электра"},{"id":"orest","name":"Орест","role":"Сын Агамемнона","intro":"Изгнанник, вернувшийся тайно, чтобы отомстить за отца.","arc":"Орест у Еврипида осторожен и нерешителен: он долго скрывает себя, убивает Эгисфа во время жертвоприношения, а перед матерью колеблется, сомневаясь в правоте Аполлона.","st":[{"i":165,"p":8,"l":"Пролог · явление третье","t":"Тайное возвращение","d":"С Пиладом приходит к границе Аргоса.","c":"","k":false},{"i":1117,"p":54,"l":"Действие второе · явление одиннадцатое","t":"Узнан","d":"Старик узнаёт его по шраму.","c":"","k":false},{"i":1355,"p":66,"l":"Действие третье · явление тринадцатое","t":"Убийство Эгисфа","d":"Вестник рассказывает, как Орест убил Эгисфа на жертвоприношении.","c":"","k":false},{"i":1526,"p":74,"l":"Действие третье · явление четырнадцатое","t":"Сомнения","d":"Видя мать, колеблется: не демон ли под видом бога велел ему убить мать?","c":"","k":true},{"i":1882,"p":92,"l":"Действие четвертое · Коммос","t":"Ужас","d":"После убийства в ужасе от сделанного.","c":"","k":false},{"i":2001,"p":98,"l":"Действие четвертое · явление семнадцатое","t":"Изгнание","d":"Кастор велит ему идти в Афины на суд Ареопага.","c":"","k":false}],"gen":"Орест"},{"id":"klitemnestra","name":"Клитемнестра","role":"Мать Электры","intro":"Царица, убившая мужа и пришедшая к дочери, чтобы совершить обряд после родов.","arc":"Клитемнестра у Еврипида усталая женщина, почти раскаявшаяся. Её оправдание (жертва Ифигении, Кассандра) звучит убедительно. Её смерть показана как жалкое убийство.","st":[{"i":1752,"p":85,"l":"Действие третье · явление пятнадцатое","t":"Спор с дочерью","d":"Оправдывается перед Электрой и входит в хижину.","c":"","k":true},{"i":1789,"p":87,"l":"Действие четвертое","t":"Смерть","d":"За сценой слышны её крики.","c":"","k":false}],"gen":"Клитемнестра"},{"id":"pahar","name":"Пахарь","role":"Микенский крестьянин","intro":"Бедный, но благородный муж Электры.","arc":"Пахарь — образ благородства простых людей: он не прикасается к царевне.","st":[{"i":86,"p":4,"l":"Пролог · явление первое","t":"Пролог","d":"Рассказывает историю дома и своего брака.","c":"","k":true}]}]};
